306	// Restore 从 Export 产生的 JSON 文本创建一个独立的钱包。
307	//
308	// 恢复不重新计时：所有截止时刻与会话到期时间沿用备份中的绝对时刻，
309	// 恢复前先按恢复时的当前时间处理全部到期请求（待审批过期、已预留超时
310	// 全额退回，释放时间仍为原截止时刻）。既有终态与历史记录不改写；过期或
311	// 吊销的会话、停用或结束的策略可以恢复，但不会重新获得授权。恢复后被
312	// 超时退回的余额可立即用于新申请，旧请求的迟到结算不能再扣走这笔钱。
313	//
314	// 空文本、非法 JSON、缺少必需数据、不支持的版本、编号重复、未知状态或
315	// 账本类型、非法金额或策略参数、悬空引用、申请会话不属于使用账户、
316	// 请求出资账户与策略不符，或余额/累计金额与请求求和不一致（含求和超出
317	// int64 范围），都返回包装了具体原因的 ErrBackupInvalid，绝不会返回
318	// 部分恢复的钱包。曾经批准成功并实际预留费用的超门槛请求（恢复时仍为
319	// 已预留，或后来已结算、已取消、已预留超时）还必须通过审批时限核对：
320	// 保存的等待截止时刻必须与提交时刻加策略等待时长、策略结束时间、申请
321	// 会话到期时间三者的最早值一致（缺失、提前、推迟都拒绝），且批准决定
322	// 必须发生在提交时刻及之后、等待截止时刻之前（恰在提交时刻批准可以
323	// 接受，恰到截止时刻批准必须拒绝）；该核对只针对备份记载的批准历史，
324	// 不以恢复时的当前时间替代批准时间，因此期限内已批准的请求即使恢复时
325	// 等待期限、申请会话或策略时间窗均已结束也照常恢复，不重新计时。
326	// 曾经完成结算的请求（直接受理与批准后预留两条路径一致）还必须通过结算
327	// 时刻核对：启用预留超时时，结算时刻必须不早于实际预留时刻且严格早于预留
328	// 截止时刻（恰在预留完成时结算可以接受，恰到截止时刻及之后必须拒绝，实际
329	// 费用为零也不例外）；时间按备份保存的完整绝对时刻比较，纳秒与时区表示均
330	// 不改变结论，关闭预留超时的请求不设此项期限。该核对同样只看备份记载的
331	// 预留与结算时刻，与恢复时的当前时间无关：期限内完成的结算即使很久以后恢复
332	// 仍保持已结算，余额、策略已花费总额与既有账本原样保留，不追加退款或超时
333	// 记录。
334	// 任一策略现存预留费用与已结算实际费用的合计严格超过其
335	// 共享累计上限时同样拒绝（同一策略的多个使用账户合并计算，不同策略分别
336	// 判断；待审批、已取消、被拒绝、已过期及预留超时的请求不占用额度），
337	// 该检查针对备份保存的资金占用状态、在恢复时的到期自动退回之前完成：
338	// 合计恰好等于上限合法，上限恰为 MaxInt64 时也不缩小可接受的金额范围。
339	// 任一账户的可用余额加上该账户在所有策略下仍处于已预留
340	// 状态的费用之和超出 int64 上限时同样拒绝（即使各请求、各策略金额分别
341	// 合法）：否则取消或预留超时的退回会使余额越界；校验在恢复时的到期
342	// 自动退回之前完成，预留尚未到期也当场拒绝。恢复出的钱包与原钱包、同一
343	// 备份恢复出的其他钱包互不影响。
344	func Restore(data []byte) (*Wallet, error) {
345		if len(bytes.TrimSpace(data)) == 0 {
346			return nil, fmt.Errorf("%w: empty backup", ErrBackupInvalid)
347		}
348	
349		var b backupV1
350		dec := json.NewDecoder(bytes.NewReader(data))
351		if err := dec.Decode(&b); err != nil {
352			return nil, fmt.Errorf("%w: malformed json: %v", ErrBackupInvalid, err)
353		}
354		// 不允许备份对象之后还有多余的 JSON 值；忽略空白。
355		if _, err := dec.Token(); err != io.EOF {
356			return nil, fmt.Errorf("%w: unexpected trailing data after backup object", ErrBackupInvalid)
357		}
358		if b.Version != backupVersion {
359			return nil, fmt.Errorf("%w: unsupported version %d (supported: %d)", ErrBackupInvalid, b.Version, backupVersion)
360		}
361	
362		w := New()
363		if err := w.restoreLocked(&b); err != nil {
364			return nil, err
365		}
366		return w, nil
367	}
368	
369	// restoreAt 仅供同包测试使用：与 Restore 相同，但显式指定恢复时刻，
370	// 便于确定性地验证恢复时的到期处理。
371	func restoreAt(data []byte, now time.Time) (*Wallet, error) {
372		if len(bytes.TrimSpace(data)) == 0 {
373			return nil, fmt.Errorf("%w: empty backup", ErrBackupInvalid)
374		}
375		var b backupV1
376		dec := json.NewDecoder(bytes.NewReader(data))
377		if err := dec.Decode(&b); err != nil {
378			return nil, fmt.Errorf("%w: malformed json: %v", ErrBackupInvalid, err)
379		}
380		if _, err := dec.Token(); err != io.EOF {
381			return nil, fmt.Errorf("%w: unexpected trailing data after backup object", ErrBackupInvalid)
382		}
383		if b.Version != backupVersion {
384			return nil, fmt.Errorf("%w: unsupported version %d (supported: %d)", ErrBackupInvalid, b.Version, backupVersion)
385		}
386		w := New()
387		w.now = func() time.Time { return now }
388		if err := w.restoreLocked(&b); err != nil {
389			return nil, err
390		}
391		return w, nil
392	}
393	
394	// restoreLocked 逐段构建并校验新钱包；任何失败都返回错误，调用方因此
395	// 绝不会拿到部分恢复的钱包。
396	func (w *Wallet) restoreLocked(b *backupV1) error {
397		// ---- 账户 ----
398		if b.Accounts == nil {
399			return fmt.Errorf("%w: missing accounts", ErrBackupInvalid)
400		}
401		accountIDs := make(map[string]struct{}, len(b.Accounts))
402		reservedByAccount := make(map[string]int64)
403		for i, a := range b.Accounts {
404			if a.ID == "" {
405				return fmt.Errorf("%w: account[%d] has empty id", ErrBackupInvalid, i)
406			}
407			if _, dup := accountIDs[a.ID]; dup {
408				return fmt.Errorf("%w: duplicate account id %q", ErrBackupInvalid, a.ID)
409			}
410			if a.Available < 0 {
411				return fmt.Errorf("%w: account %q available balance is negative: %d", ErrBackupInvalid, a.ID, a.Available)
412			}
413			if a.Reserved < 0 {
414				return fmt.Errorf("%w: account %q reserved balance is negative: %d", ErrBackupInvalid, a.ID, a.Reserved)
415			}
416			accountIDs[a.ID] = struct{}{}
417			w.accounts[a.ID] = &account{
418				id:        a.ID,
419				available: a.Available,
420				reserved:  a.Reserved,
421				createdAt: a.CreatedAt.std(),
422			}
423		}
424	
425		// ---- 会话 ----
426		if b.Sessions == nil {
427			return fmt.Errorf("%w: missing sessions", ErrBackupInvalid)
428		}
429		sessionByID := make(map[string]*session, len(b.Sessions))
430		for i, s := range b.Sessions {
431			if s.ID == "" {
432				return fmt.Errorf("%w: session[%d] has empty id", ErrBackupInvalid, i)
433			}
434			if _, dup := sessionByID[s.ID]; dup {
435				return fmt.Errorf("%w: duplicate session id %q", ErrBackupInvalid, s.ID)
436			}
437			if s.AccountID == "" || s.DeviceID == "" {
438				return fmt.Errorf("%w: session %q missing account or device id", ErrBackupInvalid, s.ID)
439			}
440			if _, ok := accountIDs[s.AccountID]; !ok {
441				return fmt.Errorf("%w: session %q references unknown account %q", ErrBackupInvalid, s.ID, s.AccountID)
442			}
443			sess := &session{
444				id:        s.ID,
445				accountID: s.AccountID,
446				deviceID:  s.DeviceID,
447				expiresAt: s.ExpiresAt.std(),
448				revoked:   s.Revoked,
449				createdAt: s.CreatedAt.std(),
450			}
451			sessionByID[s.ID] = sess
452			w.sessions[s.ID] = sess
453		}
454	
455		// ---- 策略 ----
456		if b.Policies == nil {
457			return fmt.Errorf("%w: missing policies", ErrBackupInvalid)
458		}
459		policyByID := make(map[string]*policy, len(b.Policies))
460		for i, p := range b.Policies {
461			if p.ID == "" {
462				return fmt.Errorf("%w: policy[%d] has empty id", ErrBackupInvalid, i)
463			}
464			if _, dup := policyByID[p.ID]; dup {
465				return fmt.Errorf("%w: duplicate policy id %q", ErrBackupInvalid, p.ID)
466			}
467			if err := validatePolicyParams(p); err != nil {
468				return fmt.Errorf("%w: policy %q: %v", ErrBackupInvalid, p.ID, err)
469			}
470			if _, ok := accountIDs[p.PayerAccountID]; !ok {
471				return fmt.Errorf("%w: policy %q references unknown payer account %q", ErrBackupInvalid, p.ID, p.PayerAccountID)
472			}
473			allowed := make(map[string]struct{}, len(p.AllowedAccountIDs))
474			for j, id := range p.AllowedAccountIDs {
475				if id == "" {
476					return fmt.Errorf("%w: policy %q allowed account[%d] is empty", ErrBackupInvalid, p.ID, j)
477				}
478				if _, ok := accountIDs[id]; !ok {
479					return fmt.Errorf("%w: policy %q references unknown allowed account %q", ErrBackupInvalid, p.ID, id)
480				}
481				if _, dup := allowed[id]; dup {
482					return fmt.Errorf("%w: policy %q lists allowed account %q more than once", ErrBackupInvalid, p.ID, id)
483				}
484				allowed[id] = struct{}{}
485			}
486			if p.ReservedTotal < 0 || p.SpentTotal < 0 {
487				return fmt.Errorf("%w: policy %q totals must not be negative (reserved %d spent %d)", ErrBackupInvalid, p.ID, p.ReservedTotal, p.SpentTotal)
488			}
489			po := &policy{
490				id:                   p.ID,
491				payerAccountID:       p.PayerAccountID,
492				allowedAccounts:      allowed,
493				operation:            p.Operation,
494				payee:                p.Payee,
495				startsAt:             p.StartsAt.std(),
496				endsAt:               p.EndsAt.std(),
497				maxPerRequest:        p.MaxPerRequest,
498				maxTotal:             p.MaxTotal,
499				approvalThreshold:    p.ApprovalThreshold,
500				approvalWait:         p.ApprovalWait.std(),
501				maxReserveDuration:   p.MaxReserveDuration.std(),
502				reservedTotal:        p.ReservedTotal,
503				spentTotal:           p.SpentTotal,
504				deactivated:          p.Deactivated,
505				deactivatedAt:        p.DeactivatedAt.std(),
506				deactivatorAccountID: p.DeactivatorAccountID,
507				deactivateReason:     p.DeactivateReason,
508			}
509			// 停用信息自洽：停用标志必须与停用时间/理由同时出现；停用账户必须
510			// 存在；未停用不得携带任何停用记录。
511			if po.deactivated {
512				if po.deactivatedAt.IsZero() || po.deactivateReason == "" {
513					return fmt.Errorf("%w: policy %q marked deactivated but missing deactivation time or reason", ErrBackupInvalid, p.ID)
514				}
515				if po.deactivatorAccountID != "" {
516					if _, ok := accountIDs[po.deactivatorAccountID]; !ok {
517						return fmt.Errorf("%w: policy %q deactivator references unknown account %q", ErrBackupInvalid, p.ID, po.deactivatorAccountID)
518					}
519				}
520			} else if !po.deactivatedAt.IsZero() || po.deactivatorAccountID != "" || po.deactivateReason != "" {
521				return fmt.Errorf("%w: policy %q not deactivated but carries deactivation info", ErrBackupInvalid, p.ID)
522			}
523			policyByID[p.ID] = po
524			w.policies[p.ID] = po
525		}
526	
527		// ---- 请求 ----
528		if b.Requests == nil {
529			return fmt.Errorf("%w: missing requests", ErrBackupInvalid)
530		}
531		reqKeys := make(map[requestKey]struct{}, len(b.Requests))
532		reservedSumByPolicy := make(map[string]int64)
533		spentSumByPolicy := make(map[string]int64)
534		for i, r := range b.Requests {
535			if err := validateRequestRef(r, i, accountIDs, sessionByID, policyByID); err != nil {
536				return err
537			}
538			key := requestKey{accountID: r.AccountID, requestID: r.RequestID}
539			if _, dup := reqKeys[key]; dup {
540				return fmt.Errorf("%w: duplicate request id %q under account %q", ErrBackupInvalid, r.RequestID, r.AccountID)
541			}
542			reqKeys[key] = struct{}{}
543	
544			state := RequestState(r.State)
545			if state < RequestReserved || state > RequestReservationExpired {
546				return fmt.Errorf("%w: request %q/%q has unknown state %d", ErrBackupInvalid, r.AccountID, r.RequestID, r.State)
547			}
548			if r.EstimatedFee <= 0 {
549				return fmt.Errorf("%w: request %q/%q estimated fee must be positive: %d", ErrBackupInvalid, r.AccountID, r.RequestID, r.EstimatedFee)
550			}
551			if r.ActualFee < 0 {
552				return fmt.Errorf("%w: request %q/%q actual fee is negative: %d", ErrBackupInvalid, r.AccountID, r.RequestID, r.ActualFee)
553			}
554			if r.ReserveDuration.std() < 0 {
555				return fmt.Errorf("%w: request %q/%q reserve duration is negative", ErrBackupInvalid, r.AccountID, r.RequestID)
556			}
557	
558			req := &request{
559				policyID:          r.PolicyID,
560				requestID:         r.RequestID,
561				accountID:         r.AccountID,
562				payerAccountID:    r.PayerAccountID,
563				sessionID:         r.SessionID,
564				operation:         r.Operation,
565				payee:             r.Payee,
566				estimatedFee:      r.EstimatedFee,
567				actualFee:         r.ActualFee,
568				state:             state,
569				createdAt:         r.CreatedAt.std(),
570				settledAt:         r.SettledAt.std(),
571				waitDeadline:      r.WaitDeadline.std(),
572				reservedAt:        r.ReservedAt.std(),
573				reserveDuration:   r.ReserveDuration.std(),
574				reserveDeadline:   r.ReserveDeadline.std(),
575				reserveExpiredAt:  r.ReserveExpiredAt.std(),
576				decidedAt:         r.DecidedAt.std(),
577				approverAccountID: r.ApproverAccountID,
578				rejectReason:      r.RejectReason,
579			}
580			if err := validateRequestTimingAndState(req, policyByID[r.PolicyID], sessionByID[r.SessionID]); err != nil {
581				return fmt.Errorf("%w: request %q/%q: %v", ErrBackupInvalid, r.AccountID, r.RequestID, err)
582			}
583			w.requests[key] = req
584	
585			// 累加各账户/策略“按请求推算”的金额，稍后与快照余额核对。
586			// 只有当前仍处于已预留的请求才占用账户预留与策略预留总额。
587			if state == RequestReserved {
588				sum, ok := addInt64(reservedByAccount[req.payerAccountID], req.estimatedFee)
589				if !ok {
590					return fmt.Errorf("%w: account %q reserved sum overflows int64", ErrBackupInvalid, req.payerAccountID)
591				}
592				reservedByAccount[req.payerAccountID] = sum
593				sum, ok = addInt64(reservedSumByPolicy[req.policyID], req.estimatedFee)
594				if !ok {
595					return fmt.Errorf("%w: policy %q reserved sum overflows int64", ErrBackupInvalid, req.policyID)
596				}
597				reservedSumByPolicy[req.policyID] = sum
598			}
599			if state == RequestSettled {
600				sum, ok := addInt64(spentSumByPolicy[req.policyID], req.actualFee)
601				if !ok {
602					return fmt.Errorf("%w: policy %q spent sum overflows int64", ErrBackupInvalid, req.policyID)
603				}
604				spentSumByPolicy[req.policyID] = sum
605			}
606		}
607	
608		// ---- 账户预留余额 == 已预留请求预估费用之和 ----
609		for id, acc := range w.accounts {
610			if got, want := acc.reserved, reservedByAccount[id]; got != want {
611				return fmt.Errorf("%w: account %q reserved %d != sum of reserved requests %d", ErrBackupInvalid, id, got, want)
612			}
613		}
614	
615		// ---- 可用余额 + 现存预留不得超过 int64 上限 ----
616		// 取消或预留超时会把预留全额退回可用余额：合计一旦超出 MaxInt64，
617		// 退回时余额就会越界变负。reservedByAccount 按出资账户汇总该账户在
618		// 所有策略下仍处于已预留状态的费用（待审批不冻结费用，已结算、已取消、
619		// 已预留超时的费用不再占用预留，故均不计入）。本检查必须在恢复时的
620		// 到期自动退回之前完成，使“恢复即超时退款”的备份也不能蒙混过关；
621		// 合计恰好等于上限合法（随后退回恰好得到上限金额）。
622		for id, acc := range w.accounts {
623			if _, ok := addInt64(acc.available, reservedByAccount[id]); !ok {
624				return fmt.Errorf("%w: account %q available %d plus reserved %d overflows int64", ErrBackupInvalid, id, acc.available, reservedByAccount[id])
625			}
626		}
627	
628		// ---- 策略预留总额/已花费总额 == 请求求和，且合计不得超过累计上限 ----
629		// 现存预留费用与已结算的实际费用共同占用策略的共享累计额度；同一策略的
630		// 多个使用账户合计判断，不同策略分别判断。待审批不冻结费用，已取消、被
631		// 拒绝、待审批过期、预留超时的请求均不计入，故上方求和本就不含它们。
632		// 严格超过累计上限的备份自相矛盾（正常流程在受理时就会拒绝），必须整体
633		// 拒绝；合计恰好等于上限合法。本检查针对备份保存的资金占用状态，位于
634		// 恢复时的到期自动退回之前：即使某笔已预留请求恢复时已到期、将全额
635		// 退回，也不能先退回再让原本超额的备份通过。两项金额各自为 int64、
636		// 合计越过 int64 上限时，addInt64 先捕获溢出，不能误判为额度充足。
637		for id, p := range policyByID {
638			if got, want := p.reservedTotal, reservedSumByPolicy[id]; got != want {
639				return fmt.Errorf("%w: policy %q reserved total %d != sum of reserved requests %d", ErrBackupInvalid, id, got, want)
640			}
641			if got, want := p.spentTotal, spentSumByPolicy[id]; got != want {
642				return fmt.Errorf("%w: policy %q spent total %d != sum of settled requests %d", ErrBackupInvalid, id, got, want)
643			}
644			used, ok := addInt64(reservedSumByPolicy[id], spentSumByPolicy[id])
645			if !ok {
646				return fmt.Errorf("%w: policy %q reserved %d plus spent %d overflows int64 and exceeds cumulative total limit %d",
647					ErrBackupInvalid, id, reservedSumByPolicy[id], spentSumByPolicy[id], p.maxTotal)
648			}
649			if used > p.maxTotal {
650				return fmt.Errorf("%w: policy %q reserved %d plus spent %d exceeds cumulative total limit %d",
651					ErrBackupInvalid, id, reservedSumByPolicy[id], spentSumByPolicy[id], p.maxTotal)
652			}
653		}
654	
655		// ---- 账本 ----
656		if b.Ledger == nil {
657			return fmt.Errorf("%w: missing ledger", ErrBackupInvalid)
658		}
659		w.ledger = make([]LedgerEntry, 0, len(b.Ledger))
660		for i, e := range b.Ledger {
661			kind := LedgerKind(e.Kind)
662			if kind < LedgerReserve || kind > LedgerReservationExpiration {
663				return fmt.Errorf("%w: ledger[%d] has unknown kind %d", ErrBackupInvalid, i, e.Kind)
664			}
665			if e.Amount < 0 {
666				return fmt.Errorf("%w: ledger[%d] amount is negative: %d", ErrBackupInvalid, i, e.Amount)
667			}
668			// 账本是历史留痕：其账户/请求编号允许为空或指向不存在的实体。
669			// 未被受理申请（必填字段缺失、使用账户或会话不存在等）同样会留下
670			// 拒绝记录，这些记录必须原样保留，不能因为找不到对应账户或请求而
671			// 丢弃或拒绝恢复。资金一致性由账户余额与现存请求的求和核对保证，
672			// 不依赖账本文本。PolicyID 若给出则必须存在（仅策略停用记录使用）。
673			if e.PolicyID != "" {
674				if _, ok := policyByID[e.PolicyID]; !ok {
675					return fmt.Errorf("%w: ledger[%d] references unknown policy %q", ErrBackupInvalid, i, e.PolicyID)
676				}
677			}
678			w.ledger = append(w.ledger, LedgerEntry{
679				Kind:      kind,
680				AccountID: e.AccountID,
681				RequestID: e.RequestID,
682				PolicyID:  e.PolicyID,
683				Amount:    e.Amount,
684				Reason:    e.Reason,
685				At:        e.At.std(),
686			})
687		}
688	
689		// ---- 恢复时按当前时间结清到期请求（不重新计时，只推进惰性状态） ----
690		// 处理顺序与导出保持一致：先释放已到期预留，再把到期的待审批转为过期，
691		// 两类记录均按各自截止时刻排序后追加到账本末尾。
692		now := w.now()
693		w.expireReservationsLocked(now)
694		w.expirePendingApprovalsLocked(now)
695		return nil
696	}
697	
698	// validatePolicyParams 校验策略条件与限额参数，规则与 SavePolicy 一致。
699	func validatePolicyParams(p policyBackupV1) error {
700		if p.Operation == "" || p.Payee == "" {
701			return errors.New("operation and payee are required")
702		}
703		if p.MaxPerRequest <= 0 || p.MaxTotal <= 0 {
704			return errors.New("limits must be positive")
705		}
706		if p.ApprovalThreshold < 0 {
707			return errors.New("approval threshold must not be negative")
708		}
709		if p.ApprovalThreshold > 0 {
710			if p.ApprovalThreshold > p.MaxPerRequest {
711				return fmt.Errorf("approval threshold %d exceeds per-request limit %d", p.ApprovalThreshold, p.MaxPerRequest)
712			}
713			if p.ApprovalWait <= 0 {
714				return errors.New("approval wait must be positive when approval is enabled")
715			}
716		}
717		if p.ApprovalWait < 0 || p.MaxReserveDuration < 0 {
718			return errors.New("durations must not be negative")
719		}
720		if !p.StartsAt.std().Before(p.EndsAt.std()) {
721			return errors.New("starts-at must be before ends-at")
722		}
723		if p.PayerAccountID == "" || len(p.AllowedAccountIDs) == 0 {
724			return errors.New("payer account and at least one allowed account are required")
725		}
726		return nil
727	}
728	
729	// validateRequestRef 校验请求的外键引用：账户、会话、策略均须存在；申请
730	// 会话必须属于使用账户；出资账户必须与策略一致；申请账户必须被策略允许。
731	func validateRequestRef(r requestBackupV1, i int, accounts map[string]struct{}, sessions map[string]*session, policies map[string]*policy) error {
732		where := fmt.Sprintf("request[%d] %q/%q", i, r.AccountID, r.RequestID)
733		if r.RequestID == "" || r.AccountID == "" || r.PolicyID == "" || r.SessionID == "" {
734			return fmt.Errorf("%w: %s missing required id (account/request/policy/session)", ErrBackupInvalid, where)
735		}
736		if _, ok := accounts[r.AccountID]; !ok {
737			return fmt.Errorf("%w: %s references unknown usage account %q", ErrBackupInvalid, where, r.AccountID)
738		}
739		if _, ok := accounts[r.PayerAccountID]; !ok {
740			return fmt.Errorf("%w: %s references unknown payer account %q", ErrBackupInvalid, where, r.PayerAccountID)
741		}
742		sess, ok := sessions[r.SessionID]
743		if !ok {
744			return fmt.Errorf("%w: %s references unknown session %q", ErrBackupInvalid, where, r.SessionID)
745		}
746		// 申请会话必须属于使用账户。
747		if sess.accountID != r.AccountID {
748			return fmt.Errorf("%w: %s session %q belongs to account %q, not usage account %q", ErrBackupInvalid, where, r.SessionID, sess.accountID, r.AccountID)
749		}
750		p, ok := policies[r.PolicyID]
751		if !ok {
752			return fmt.Errorf("%w: %s references unknown policy %q", ErrBackupInvalid, where, r.PolicyID)
753		}
754		// 请求出资账户必须与策略出资账户一致。
755		if r.PayerAccountID != p.payerAccountID {
756			return fmt.Errorf("%w: %s payer account %q does not match policy %q payer %q", ErrBackupInvalid, where, r.PayerAccountID, r.PolicyID, p.payerAccountID)
757		}
758		if _, ok := p.allowedAccounts[r.AccountID]; !ok {
759			return fmt.Errorf("%w: %s usage account %q is not allowed by policy %q", ErrBackupInvalid, where, r.AccountID, r.PolicyID)
760		}
761		return nil
762	}
763	
764	// validateReserveTiming 校验预留计时三元组自洽：duration 必须非负；
765	// duration>0 时 reservedAt 必填且 reserveDeadline 必须等于
766	// reservedAt+duration；duration==0 时 reserveDeadline 必须为零。
767	// reservedAt 是否必填由各状态自行决定（待审批取消的请求两者都没有）。
768	func validateReserveTiming(r *request) error {
769		if r.reserveDuration < 0 {
770			return errors.New("reserve duration must not be negative")
771		}
772		if r.reserveDuration > 0 {
773			if r.reservedAt.IsZero() {
774				return errors.New("reserve duration set but reserved_at is missing")
775			}
776			want := r.reservedAt.Add(r.reserveDuration)
777			if !r.reserveDeadline.Equal(want) {
778				return fmt.Errorf("reserve deadline %v does not match reserved_at+duration %v", r.reserveDeadline, want)
779			}
780		} else if !r.reserveDeadline.IsZero() {
781			return errors.New("reserve deadline set while reserve duration is zero")
782		}
783		return nil
784	}
785	
786	// validateSettlementTiming 校验已结算请求的结算时刻必须是正常结算能够产生的
787	// 历史：不早于实际预留时刻（恰在预留完成时结算可以接受）；当请求启用了预留
788	// 超时（reserveDuration>0，此时 reserveDeadline 已由 validateReserveTiming
789	// 确认为 reservedAt+duration）时，还必须严格早于预留截止时刻——恰到截止时刻
790	// 及之后预留已按超时规则全额退回，任何结算（含实际费用为零）都不可能成功。
791	//
792	// 时间一律按保存的完整时刻以 time.Time 的绝对瞬间比较（Equal/Before）：
793	// 纳秒精度保留，截止前不足一秒的合法结算不会被当成超时；不同时区表示的同一
794	// 时刻判定相同。关闭预留超时（reserveDuration==0）时没有截止时刻，沿用原有
795	// 结算规则、不人为增加期限。该校验只针对备份记载的预留与结算时刻，与恢复时
796	// 的当前时间无关：期限内完成的结算在很久以后恢复仍是已结算。
797	func validateSettlementTiming(r *request) error {
798		if r.settledAt.Before(r.reservedAt) {
799			return fmt.Errorf("settled_at %v is before reserved_at %v", r.settledAt, r.reservedAt)
800		}
801		if r.reserveDuration > 0 && !r.settledAt.Before(r.reserveDeadline) {
802			return fmt.Errorf("settled_at %v is not within the valid reserve window ending strictly before reserve deadline %v", r.settledAt, r.reserveDeadline)
803		}
804		return nil
805	}
806	
807	// validateRequestTimingAndState 校验请求状态与其计时/金额字段自洽，并与
808	// 不可变的策略条件、申请会话保持一致，防止任意状态搭配任意时间戳的损坏
809	// 备份。sess 为该请求的申请会话。
810	func validateRequestTimingAndState(r *request, p *policy, sess *session) error {
811		if r.createdAt.IsZero() {
812			return errors.New("request missing created_at")
813		}
814		if r.operation == "" || r.payee == "" {
815			return errors.New("operation and payee are required")
816		}
817		if r.operation != p.operation || r.payee != p.payee {
818			return fmt.Errorf("operation/payee do not match policy %q", p.id)
819		}
820		if r.estimatedFee > p.maxPerRequest {
821			return fmt.Errorf("estimated fee %d exceeds policy per-request limit %d", r.estimatedFee, p.maxPerRequest)
822		}
823		if r.approverAccountID != "" && r.approverAccountID != r.payerAccountID {
824			return fmt.Errorf("approver account %q is not the payer %q", r.approverAccountID, r.payerAccountID)
825		}
826		if r.actualFee > r.estimatedFee {
827			return fmt.Errorf("actual fee %d exceeds estimated fee %d", r.actualFee, r.estimatedFee)
828		}
829	
830		// 申请是否必须走过审批由不可变策略门槛决定：费用严格超过正门槛的请求
831		// 只能来自待审批流程；其余请求只能直接预留。
832		approvalRequired := p.approvalThreshold > 0 && r.estimatedFee > p.approvalThreshold
833		reservedOrigin := !r.reservedAt.IsZero()
834	
835		switch r.state {
836		case RequestReserved, RequestSettled, RequestReservationExpired:
837			// 这三类一定发生过预留。
838			if err := validateReservedOrigin(r, p, sess, approvalRequired, reservedOrigin); err != nil {
839				return err
840			}
841		case RequestPendingApproval, RequestRejected, RequestExpired:
842			// 这三类一定从未预留，且必须来自开启审批的策略。
843			if err := validatePendingOrigin(r, p, approvalRequired, reservedOrigin); err != nil {
844				return err
845			}
846		case RequestCancelled:
847			// 取消可能来自待审批（从未预留）或已预留。
848			if reservedOrigin {
849				if err := validateReservedOrigin(r, p, sess, approvalRequired, true); err != nil {
850					return err
851				}
852			} else {
853				if err := validatePendingOrigin(r, p, approvalRequired, false); err != nil {
854					return err
855				}
856			}
857		default:
858			return fmt.Errorf("unknown state %d", r.state)
859		}
860	
861		switch r.state {
862		case RequestReserved:
863			// 启用超时时 deadline 必须等于 reservedAt + 时长，未启用时为零，
864			// 且不得已记录超时。
865			if err := validateReserveTiming(r); err != nil {
866				return err
867			}
868			if !r.reserveExpiredAt.IsZero() {
869				return errors.New("reserved request must not carry reserve-expired time")
870			}
871			if r.actualFee != 0 || !r.settledAt.IsZero() {
872				return errors.New("reserved request must not be settled")
873			}
874			if r.rejectReason != "" {
875				return errors.New("reserved request must not carry a reject reason")
876			}
877		case RequestSettled:
878			if r.settledAt.IsZero() {
879				return errors.New("settled request missing settled_at")
880			}
881			if !r.reserveExpiredAt.IsZero() {
882				return errors.New("settled request must not carry reserve-expired time")
883			}
884			if err := validateReserveTiming(r); err != nil {
885				return err
886			}
887			// 结算时刻必须落在有效预留期内：启用预留超时时严格早于截止时刻。
888			if err := validateSettlementTiming(r); err != nil {
889				return err
890			}
891			if r.rejectReason != "" {
892				return errors.New("settled request must not carry a reject reason")
893			}
894		case RequestCancelled:
895			if r.actualFee != 0 || !r.settledAt.IsZero() {
896				return errors.New("cancelled request must not be settled")
897			}
898			if !r.reserveExpiredAt.IsZero() {
899				return errors.New("cancelled request must not carry reserve-expired time")
900			}
901			if r.rejectReason != "" {
902				return errors.New("cancelled request must not carry a reject reason")
903			}
904			if reservedOrigin {
905				if err := validateReserveTiming(r); err != nil {
906					return err
907				}
908			} else {
909				// 待审批取消：决定时间必填。
910				if r.decidedAt.IsZero() {
911					return errors.New("cancelled-from-pending request missing decided_at")
912				}
913			}
914		case RequestPendingApproval:
915			// 待审批不冻结余额：不得有实际费用，且等待期限必须等于
916			// min(提交+等待时长, 策略结束, 申请会话到期)。
917			if r.actualFee != 0 || !r.settledAt.IsZero() {
918				return errors.New("pending request must not be settled")
919			}
920			if r.waitDeadline.IsZero() {
921				return errors.New("pending request missing wait deadline")
922			}
923			if r.approverAccountID != "" {
924				return errors.New("pending request must not carry an approver")
925			}
926			if r.rejectReason != "" {
927				return errors.New("pending request must not carry a reject reason")
928			}
929			if !r.waitDeadline.Equal(expectedWaitDeadline(r, p, sess)) {
930				return fmt.Errorf("wait deadline %v does not match min(created+wait, policy end, session expiry) %v", r.waitDeadline, expectedWaitDeadline(r, p, sess))
931			}
932		case RequestRejected:
933			if r.decidedAt.IsZero() || r.rejectReason == "" {
934				return errors.New("rejected request missing decided_at or reason")
935			}
936		case RequestExpired:
937			if r.decidedAt.IsZero() {
938				return errors.New("expired request missing decided_at")
939			}
940			if r.rejectReason != "" {
941				return errors.New("expired request must not carry a reject reason")
942			}
943			// 惰性/停用过期的决定时刻不可能早于等待截止时刻。
944			if r.decidedAt.Before(r.waitDeadline) {
945				return errors.New("expired request decided before its wait deadline")
946			}
947		case RequestReservationExpired:
948			if r.reserveDuration <= 0 {
949				return errors.New("reservation-expired request must have a positive reserve duration")
950			}
951			if err := validateReserveTiming(r); err != nil {
952				return err
953			}
954			if !r.reserveExpiredAt.Equal(r.reserveDeadline) {
955				return errors.New("reserve-expired-at must equal reserve deadline")
956			}
957			if r.actualFee != 0 || !r.settledAt.IsZero() {
958				return errors.New("reservation-expired request must not be settled")
959			}
960			if r.rejectReason != "" {
961				return errors.New("reservation-expired request must not carry a reject reason")
962			}
963		}
964		return nil
965	}
966	
967	// expectedWaitDeadline 计算审批路径请求的等待截止时刻：提交时刻 + 策略
968	// 等待时长、策略结束时间、申请会话到期时间三者中的最早值。待审批与已批准
969	// 预留的请求保存的等待截止时刻都必须与该值一致。
970	func expectedWaitDeadline(r *request, p *policy, sess *session) time.Time {
971		want := r.createdAt.Add(p.approvalWait)
972		if p.endsAt.Before(want) {
973			want = p.endsAt
974		}
975		if sess.expiresAt.Before(want) {
976			want = sess.expiresAt
977		}
978		return want
979	}
980	
981	// validateApprovalTiming 校验“经批准后预留”的请求保存的等待期限与批准
982	// 时刻自洽，防止备份中的资金占用绕过正常审批等待期限：
983	//   - 等待截止时刻不得缺失，且必须等于提交时刻+等待时长、策略结束时间、
984	//     申请会话到期时间三者的最早值，提前或推迟都拒绝；
985	//   - 批准（决定/预留）时刻必须不早于提交时刻（恰在提交时刻批准可以接受），
986	//     且严格早于等待截止时刻：恰到截止时刻的批准在正常审批中不可能发生
987	//     （截止时刻及之后请求只能进入待审批过期终态）。
988	//
989	// 该校验只针对备份记载的批准历史，与恢复时的当前时间无关：期限内已批准的
990	// 请求在恢复时即使等待期限、申请会话或策略时间窗均已结束也照常恢复。
991	func validateApprovalTiming(r *request, p *policy, sess *session) error {
992		if r.waitDeadline.IsZero() {
993			return errors.New("approved request missing wait deadline")
994		}
995		want := expectedWaitDeadline(r, p, sess)
996		if !r.waitDeadline.Equal(want) {
997			return fmt.Errorf("wait deadline %v does not match min(created+wait, policy end, session expiry) %v", r.waitDeadline, want)
998		}
999		if r.decidedAt.Before(r.createdAt) {
1000			return fmt.Errorf("approval decided_at %v is before created_at %v", r.decidedAt, r.createdAt)
1001		}
1002		if !r.decidedAt.Before(r.waitDeadline) {
1003			return fmt.Errorf("approval decided_at %v is not strictly before wait deadline %v", r.decidedAt, r.waitDeadline)
1004		}
1005		return nil
1006	}
1007	
1008	// validateReservedOrigin 校验“发生过预留”的请求：预留计时字段必须齐全、
1009	// 预留时长快照必须与策略一致，且审批路径（批准人、决定时间、等待期限）与
1010	// 费用/门槛相匹配。对所有发生过预留的状态（已预留、已结算、预留超时、
1011	// 已预留后取消）统一适用：超门槛的必须经出资账户在等待期限内于预留时刻
1012	// 批准，未超门槛的直接受理、不得携带批准人或决定时间。
1013	func validateReservedOrigin(r *request, p *policy, sess *session, approvalRequired, reservedOrigin bool) error {
1014		if !reservedOrigin {
1015			return errors.New("request is in a reserved-origin state but missing reserved_at")
1016		}
1017		if r.reserveDuration != p.maxReserveDuration {
1018			return fmt.Errorf("reserve duration %v does not match policy max reserve duration %v", r.reserveDuration, p.maxReserveDuration)
1019		}
1020		if approvalRequired {
1021			if r.approverAccountID != r.payerAccountID {
1022				return errors.New("above-threshold request was reserved without payer approval")
1023			}
1024			if !r.decidedAt.Equal(r.reservedAt) {
1025				return errors.New("approved request decided_at must equal reserved_at")
1026			}
1027			// 等待截止时刻与批准时刻必须是正常审批流程能够产生的历史：即使该
1028			// 预留后来已经结算、取消或超时退回，也不放宽这一要求。
1029			if err := validateApprovalTiming(r, p, sess); err != nil {
1030				return err
1031			}
1032		} else {
1033			if r.approverAccountID != "" {
1034				return errors.New("below-threshold request must not carry an approver")
1035			}
1036			if !r.decidedAt.IsZero() {
1037				return errors.New("directly reserved request must not carry decided_at")
1038			}
1039		}
1040		return nil
1041	}
1042	
1043	// validatePendingOrigin 校验“从未预留”的待审批系请求：不得携带任何预留
1044	// 计时字段，且策略必须开启审批、费用必须严格超过门槛。
1045	func validatePendingOrigin(r *request, p *policy, approvalRequired, reservedOrigin bool) error {
1046		if reservedOrigin {
1047			return errors.New("request is in a pending-origin state but carries reserved_at")
1048		}
1049		if !approvalRequired {
1050			return errors.New("request is in an approval state although policy approval is not enabled for its fee")
1051		}
1052		if !r.reserveDeadline.IsZero() || !r.reserveExpiredAt.IsZero() || r.reserveDuration != 0 {
1053			return errors.New("pending-origin request must not carry reserve timing")
1054		}
1055		return nil
1056	}
1057

file.content:
package wallet

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"math"
	"sort"
	"time"
)

// backupVersion 为当前支持的备份格式版本号。
const backupVersion = 1

// ErrBackupInvalid 表示备份文本为空、无法解析、缺少必需数据、版本不支持
// 或内容自相矛盾。恢复接口返回包装了具体原因的错误；任何校验失败都不会
// 返回部分恢复的钱包。
var ErrBackupInvalid = errors.New("wallet: invalid backup")

// timeJSON 以 RFC3339Nano（带纳秒与时区）序列化时间，零值时间序列化为
// 空字符串，避免把“尚未发生”的计时信息误恢复成公元元年。
type timeJSON time.Time

func (t timeJSON) MarshalJSON() ([]byte, error) {
	tm := time.Time(t)
	if tm.IsZero() {
		return []byte(`""`), nil
	}
	return json.Marshal(tm.Format(time.RFC3339Nano))
}

func (t *timeJSON) UnmarshalJSON(data []byte) error {
	var s string
	if err := json.Unmarshal(data, &s); err != nil {
		return err
	}
	if s == "" {
		*t = timeJSON(time.Time{})
		return nil
	}
	tm, err := time.Parse(time.RFC3339Nano, s)
	if err != nil {
		// 宽容解析无纳秒的 RFC3339。
		tm, err = time.Parse(time.RFC3339, s)
		if err != nil {
			return err
		}
	}
	*t = timeJSON(tm)
	return nil
}

func (t timeJSON) std() time.Time { return time.Time(t) }

// durationJSON 以 int64 纳秒序列化时长，保持精确往返。
type durationJSON time.Duration

func (d durationJSON) MarshalJSON() ([]byte, error) {
	return json.Marshal(int64(d))
}

func (d *durationJSON) UnmarshalJSON(data []byte) error {
	var n int64
	if err := json.Unmarshal(data, &n); err != nil {
		return err
	}
	*d = durationJSON(n)
	return nil
}

func (d durationJSON) std() time.Duration { return time.Duration(d) }

type accountBackupV1 struct {
	ID        string   `json:"id"`
	Available int64    `json:"available"`
	Reserved  int64    `json:"reserved"`
	CreatedAt timeJSON `json:"created_at"`
}

type sessionBackupV1 struct {
	ID        string   `json:"id"`
	AccountID string   `json:"account_id"`
	DeviceID  string   `json:"device_id"`
	ExpiresAt timeJSON `json:"expires_at"`
	Revoked   bool     `json:"revoked"`
	CreatedAt timeJSON `json:"created_at"`
}

type policyBackupV1 struct {
	ID                   string       `json:"id"`
	PayerAccountID       string       `json:"payer_account_id"`
	AllowedAccountIDs    []string     `json:"allowed_account_ids"`
	Operation            string       `json:"operation"`
	Payee                string       `json:"payee"`
	StartsAt             timeJSON     `json:"starts_at"`
	EndsAt               timeJSON     `json:"ends_at"`
	MaxPerRequest        int64        `json:"max_per_request"`
	MaxTotal             int64        `json:"max_total"`
	ApprovalThreshold    int64        `json:"approval_threshold"`
	ApprovalWait         durationJSON `json:"approval_wait_nanos"`
	MaxReserveDuration   durationJSON `json:"max_reserve_duration_nanos"`
	ReservedTotal        int64        `json:"reserved_total"`
	SpentTotal           int64        `json:"spent_total"`
	Deactivated          bool         `json:"deactivated"`
	DeactivatedAt        timeJSON     `json:"deactivated_at"`
	DeactivatorAccountID string       `json:"deactivator_account_id"`
	DeactivateReason     string       `json:"deactivate_reason"`
}

type requestBackupV1 struct {
	PolicyID          string       `json:"policy_id"`
	RequestID         string       `json:"request_id"`
	AccountID         string       `json:"account_id"`
	PayerAccountID    string       `json:"payer_account_id"`
	SessionID         string       `json:"session_id"`
	Operation         string       `json:"operation"`
	Payee             string       `json:"payee"`
	EstimatedFee      int64        `json:"estimated_fee"`
	ActualFee         int64        `json:"actual_fee"`
	State             int          `json:"state"`
	CreatedAt         timeJSON     `json:"created_at"`
	SettledAt         timeJSON     `json:"settled_at"`
	WaitDeadline      timeJSON     `json:"wait_deadline"`
	ReservedAt        timeJSON     `json:"reserved_at"`
	ReserveDuration   durationJSON `json:"reserve_duration_nanos"`
	ReserveDeadline   timeJSON     `json:"reserve_deadline"`
	ReserveExpiredAt  timeJSON     `json:"reserve_expired_at"`
	DecidedAt         timeJSON     `json:"decided_at"`
	ApproverAccountID string       `json:"approver_account_id"`
	RejectReason      string       `json:"reject_reason"`
}

type ledgerEntryBackupV1 struct {
	Kind      int      `json:"kind"`
	AccountID string   `json:"account_id"`
	RequestID string   `json:"request_id"`
	PolicyID  string   `json:"policy_id"`
	Amount    int64    `json:"amount"`
	Reason    string   `json:"reason"`
	At        timeJSON `json:"at"`
}

type backupV1 struct {
	Version    int                   `json:"version"`
	ExportedAt timeJSON              `json:"exported_at"`
	Accounts   []accountBackupV1     `json:"accounts"`
	Sessions   []sessionBackupV1     `json:"sessions"`
	Policies   []policyBackupV1      `json:"policies"`
	Requests   []requestBackupV1     `json:"requests"`
	Ledger     []ledgerEntryBackupV1 `json:"ledger"`
}

// Export 将当前钱包导出为带版本号的 JSON 文本。
//
// 导出在钱包同一把全局锁内完成，对应某一时刻的完整状态：可与申请、
// 批准、拒绝、吊销、停用、结算或取消并发，不会出现只有余额变化却缺少
// 对应请求或账本的半截状态。导出前先按导出时的当前时间处理全部到期
// 请求——待审批到达等待截止时刻后进入过期终态并留痕，已预留到达预留
// 截止时刻后全额退回（释放时间仍为原截止时刻）并留下退款及超时记录；
// 未到期请求继续等待或预留。
//
// 备份保留账户余额、会话的设备绑定与吊销状态、策略条件及停用信息、
// 全部请求的申请内容、状态、审批决定与全部计时信息，以及按原顺序排列
// 的账本（包括未被受理申请的拒绝记录）。空钱包也能导出并恢复；导出
// 本身不新增任何账本记录（到期处理带来的记录除外）。
//
// 备份不能暂停期限，因此导出不改变任何请求的计时基准；导出后的钱包
// 与备份文本、以及从该备份恢复出的钱包之间互不影响。
func (w *Wallet) Export() ([]byte, error) {
	w.mu.Lock()
	defer w.mu.Unlock()

	now := w.now()
	// 导出快照前结清全部到期项，保证备份对应一个完整状态：已预留超时的按
	// 原截止时刻全额退回并留两条记录（按截止时刻排序），待审批过期的留
	// 状态记录（按等待截止时刻排序）。
	w.expireReservationsLocked(now)
	w.expirePendingApprovalsLocked(now)

	b := backupV1{
		Version:    backupVersion,
		ExportedAt: timeJSON(now),
		Accounts:   make([]accountBackupV1, 0, len(w.accounts)),
		Sessions:   make([]sessionBackupV1, 0, len(w.sessions)),
		Policies:   make([]policyBackupV1, 0, len(w.policies)),
		Requests:   make([]requestBackupV1, 0, len(w.requests)),
		Ledger:     make([]ledgerEntryBackupV1, 0, len(w.ledger)),
	}

	// map 迭代顺序不确定；集合类数据按编号排序，使备份可逐字节复现。
	for _, a := range w.accounts {
		b.Accounts = append(b.Accounts, accountBackupV1{
			ID:        a.id,
			Available: a.available,
			Reserved:  a.reserved,
			CreatedAt: timeJSON(a.createdAt),
		})
	}
	sort.Slice(b.Accounts, func(i, j int) bool { return b.Accounts[i].ID < b.Accounts[j].ID })

	for _, s := range w.sessions {
		b.Sessions = append(b.Sessions, sessionBackupV1{
			ID:        s.id,
			AccountID: s.accountID,
			DeviceID:  s.deviceID,
			ExpiresAt: timeJSON(s.expiresAt),
			Revoked:   s.revoked,
			CreatedAt: timeJSON(s.createdAt),
		})
	}
	sort.Slice(b.Sessions, func(i, j int) bool { return b.Sessions[i].ID < b.Sessions[j].ID })

	for _, p := range w.policies {
		allowed := make([]string, 0, len(p.allowedAccounts))
		for id := range p.allowedAccounts {
			allowed = append(allowed, id)
		}
		sort.Strings(allowed)
		b.Policies = append(b.Policies, policyBackupV1{
			ID:                   p.id,
			PayerAccountID:       p.payerAccountID,
			AllowedAccountIDs:    allowed,
			Operation:            p.operation,
			Payee:                p.payee,
			StartsAt:             timeJSON(p.startsAt),
			EndsAt:               timeJSON(p.endsAt),
			MaxPerRequest:        p.maxPerRequest,
			MaxTotal:             p.maxTotal,
			ApprovalThreshold:    p.approvalThreshold,
			ApprovalWait:         durationJSON(p.approvalWait),
			MaxReserveDuration:   durationJSON(p.maxReserveDuration),
			ReservedTotal:        p.reservedTotal,
			SpentTotal:           p.spentTotal,
			Deactivated:          p.deactivated,
			DeactivatedAt:        timeJSON(p.deactivatedAt),
			DeactivatorAccountID: p.deactivatorAccountID,
			DeactivateReason:     p.deactivateReason,
		})
	}
	sort.Slice(b.Policies, func(i, j int) bool { return b.Policies[i].ID < b.Policies[j].ID })

	for _, r := range w.requests {
		b.Requests = append(b.Requests, requestBackupV1{
			PolicyID:          r.policyID,
			RequestID:         r.requestID,
			AccountID:         r.accountID,
			PayerAccountID:    r.payerAccountID,
			SessionID:         r.sessionID,
			Operation:         r.operation,
			Payee:             r.payee,
			EstimatedFee:      r.estimatedFee,
			ActualFee:         r.actualFee,
			State:             int(r.state),
			CreatedAt:         timeJSON(r.createdAt),
			SettledAt:         timeJSON(r.settledAt),
			WaitDeadline:      timeJSON(r.waitDeadline),
			ReservedAt:        timeJSON(r.reservedAt),
			ReserveDuration:   durationJSON(r.reserveDuration),
			ReserveDeadline:   timeJSON(r.reserveDeadline),
			ReserveExpiredAt:  timeJSON(r.reserveExpiredAt),
			DecidedAt:         timeJSON(r.decidedAt),
			ApproverAccountID: r.approverAccountID,
			RejectReason:      r.rejectReason,
		})
	}
	sort.Slice(b.Requests, func(i, j int) bool {
		if b.Requests[i].AccountID != b.Requests[j].AccountID {
			return b.Requests[i].AccountID < b.Requests[j].AccountID
		}
		return b.Requests[i].RequestID < b.Requests[j].RequestID
	})

	// 账本严格按原顺序导出，不重新排序。
	for _, e := range w.ledger {
		b.Ledger = append(b.Ledger, ledgerEntryBackupV1{
			Kind:      int(e.Kind),
			AccountID: e.AccountID,
			RequestID: e.RequestID,
			PolicyID:  e.PolicyID,
			Amount:    e.Amount,
			Reason:    e.Reason,
			At:        timeJSON(e.At),
		})
	}

	out, err := json.Marshal(&b)
	if err != nil {
		return nil, fmt.Errorf("%w: encode: %v", ErrBackupInvalid, err)
	}
	return out, nil
}

// addInt64 在求和时检测 int64 溢出；超出范围返回 false。
func addInt64(sum, x int64) (int64, bool) {
	if x > 0 && sum > math.MaxInt64-x {
		return 0, false
	}
	if x < 0 && sum < math.MinInt64-x {
		return 0, false
	}
	return sum + x, true
}

// Restore 从 Export 产生的 JSON 文本创建一个独立的钱包。
//
// 恢复不重新计时：所有截止时刻与会话到期时间沿用备份中的绝对时刻，
// 恢复前先按恢复时的当前时间处理全部到期请求（待审批过期、已预留超时
// 全额退回，释放时间仍为原截止时刻）。既有终态与历史记录不改写；过期或
// 吊销的会话、停用或结束的策略可以恢复，但不会重新获得授权。恢复后被
// 超时退回的余额可立即用于新申请，旧请求的迟到结算不能再扣走这笔钱。
//
// 空文本、非法 JSON、缺少必需数据、不支持的版本、编号重复、未知状态或
// 账本类型、非法金额或策略参数、悬空引用、申请会话不属于使用账户、
// 请求出资账户与策略不符，或余额/累计金额与请求求和不一致（含求和超出
// int64 范围），都返回包装了具体原因的 ErrBackupInvalid，绝不会返回
// 部分恢复的钱包。曾经批准成功并实际预留费用的超门槛请求（恢复时仍为
// 已预留，或后来已结算、已取消、已预留超时）还必须通过审批时限核对：
// 保存的等待截止时刻必须与提交时刻加策略等待时长、策略结束时间、申请
// 会话到期时间三者的最早值一致（缺失、提前、推迟都拒绝），且批准决定
// 必须发生在提交时刻及之后、等待截止时刻之前（恰在提交时刻批准可以
// 接受，恰到截止时刻批准必须拒绝）；该核对只针对备份记载的批准历史，
// 不以恢复时的当前时间替代批准时间，因此期限内已批准的请求即使恢复时
// 等待期限、申请会话或策略时间窗均已结束也照常恢复，不重新计时。
// 曾经完成结算的请求（直接受理与批准后预留两条路径一致）还必须通过结算
// 时刻核对：启用预留超时时，结算时刻必须不早于实际预留时刻且严格早于预留
// 截止时刻（恰在预留完成时结算可以接受，恰到截止时刻及之后必须拒绝，实际
// 费用为零也不例外）；时间按备份保存的完整绝对时刻比较，纳秒与时区表示均
// 不改变结论，关闭预留超时的请求不设此项期限。该核对同样只看备份记载的
// 预留与结算时刻，与恢复时的当前时间无关：期限内完成的结算即使很久以后恢复
// 仍保持已结算，余额、策略已花费总额与既有账本原样保留，不追加退款或超时
// 记录。
// 任一策略现存预留费用与已结算实际费用的合计严格超过其
// 共享累计上限时同样拒绝（同一策略的多个使用账户合并计算，不同策略分别
// 判断；待审批、已取消、被拒绝、已过期及预留超时的请求不占用额度），
// 该检查针对备份保存的资金占用状态、在恢复时的到期自动退回之前完成：
// 合计恰好等于上限合法，上限恰为 MaxInt64 时也不缩小可接受的金额范围。
// 任一账户的可用余额加上该账户在所有策略下仍处于已预留
// 状态的费用之和超出 int64 上限时同样拒绝（即使各请求、各策略金额分别
// 合法）：否则取消或预留超时的退回会使余额越界；校验在恢复时的到期
// 自动退回之前完成，预留尚未到期也当场拒绝。恢复出的钱包与原钱包、同一
// 备份恢复出的其他钱包互不影响。
func Restore(data []byte) (*Wallet, error) {
	if len(bytes.TrimSpace(data)) == 0 {
		return nil, fmt.Errorf("%w: empty backup", ErrBackupInvalid)
	}

	var b backupV1
	dec := json.NewDecoder(bytes.NewReader(data))
	if err := dec.Decode(&b); err != nil {
		return nil, fmt.Errorf("%w: malformed json: %v", ErrBackupInvalid, err)
	}
	// 不允许备份对象之后还有多余的 JSON 值；忽略空白。
	if _, err := dec.Token(); err != io.EOF {
		return nil, fmt.Errorf("%w: unexpected trailing data after backup object", ErrBackupInvalid)
	}
	if b.Version != backupVersion {
		return nil, fmt.Errorf("%w: unsupported version %d (supported: %d)", ErrBackupInvalid, b.Version, backupVersion)
	}

	w := New()
	if err := w.restoreLocked(&b); err != nil {
		return nil, err
	}
	return w, nil
}

// restoreAt 仅供同包测试使用：与 Restore 相同，但显式指定恢复时刻，
// 便于确定性地验证恢复时的到期处理。
func restoreAt(data []byte, now time.Time) (*Wallet, error) {
	if len(bytes.TrimSpace(data)) == 0 {
		return nil, fmt.Errorf("%w: empty backup", ErrBackupInvalid)
	}
	var b backupV1
	dec := json.NewDecoder(bytes.NewReader(data))
	if err := dec.Decode(&b); err != nil {
		return nil, fmt.Errorf("%w: malformed json: %v", ErrBackupInvalid, err)
	}
	if _, err := dec.Token(); err != io.EOF {
		return nil, fmt.Errorf("%w: unexpected trailing data after backup object", ErrBackupInvalid)
	}
	if b.Version != backupVersion {
		return nil, fmt.Errorf("%w: unsupported version %d (supported: %d)", ErrBackupInvalid, b.Version, backupVersion)
	}
	w := New()
	w.now = func() time.Time { return now }
	if err := w.restoreLocked(&b); err != nil {
		return nil, err
	}
	return w, nil
}

// restoreLocked 逐段构建并校验新钱包；任何失败都返回错误，调用方因此
// 绝不会拿到部分恢复的钱包。
func (w *Wallet) restoreLocked(b *backupV1) error {
	// ---- 账户 ----
	if b.Accounts == nil {
		return fmt.Errorf("%w: missing accounts", ErrBackupInvalid)
	}
	accountIDs := make(map[string]struct{}, len(b.Accounts))
	reservedByAccount := make(map[string]int64)
	for i, a := range b.Accounts {
		if a.ID == "" {
			return fmt.Errorf("%w: account[%d] has empty id", ErrBackupInvalid, i)
		}
		if _, dup := accountIDs[a.ID]; dup {
			return fmt.Errorf("%w: duplicate account id %q", ErrBackupInvalid, a.ID)
		}
		if a.Available < 0 {
			return fmt.Errorf("%w: account %q available balance is negative: %d", ErrBackupInvalid, a.ID, a.Available)
		}
		if a.Reserved < 0 {
			return fmt.Errorf("%w: account %q reserved balance is negative: %d", ErrBackupInvalid, a.ID, a.Reserved)
		}
		accountIDs[a.ID] = struct{}{}
		w.accounts[a.ID] = &account{
			id:        a.ID,
			available: a.Available,
			reserved:  a.Reserved,
			createdAt: a.CreatedAt.std(),
		}
	}

	// ---- 会话 ----
	if b.Sessions == nil {
		return fmt.Errorf("%w: missing sessions", ErrBackupInvalid)
	}
	sessionByID := make(map[string]*session, len(b.Sessions))
	for i, s := range b.Sessions {
		if s.ID == "" {
			return fmt.Errorf("%w: session[%d] has empty id", ErrBackupInvalid, i)
		}
		if _, dup := sessionByID[s.ID]; dup {
			return fmt.Errorf("%w: duplicate session id %q", ErrBackupInvalid, s.ID)
		}
		if s.AccountID == "" || s.DeviceID == "" {
			return fmt.Errorf("%w: session %q missing account or device id", ErrBackupInvalid, s.ID)
		}
		if _, ok := accountIDs[s.AccountID]; !ok {
			return fmt.Errorf("%w: session %q references unknown account %q", ErrBackupInvalid, s.ID, s.AccountID)
		}
		sess := &session{
			id:        s.ID,
			accountID: s.AccountID,
			deviceID:  s.DeviceID,
			expiresAt: s.ExpiresAt.std(),
			revoked:   s.Revoked,
			createdAt: s.CreatedAt.std(),
		}
		sessionByID[s.ID] = sess
		w.sessions[s.ID] = sess
	}

	// ---- 策略 ----
	if b.Policies == nil {
		return fmt.Errorf("%w: missing policies", ErrBackupInvalid)
	}
	policyByID := make(map[string]*policy, len(b.Policies))
	for i, p := range b.Policies {
		if p.ID == "" {
			return fmt.Errorf("%w: policy[%d] has empty id", ErrBackupInvalid, i)
		}
		if _, dup := policyByID[p.ID]; dup {
			return fmt.Errorf("%w: duplicate policy id %q", ErrBackupInvalid, p.ID)
		}
		if err := validatePolicyParams(p); err != nil {
			return fmt.Errorf("%w: policy %q: %v", ErrBackupInvalid, p.ID, err)
		}
		if _, ok := accountIDs[p.PayerAccountID]; !ok {
			return fmt.Errorf("%w: policy %q references unknown payer account %q", ErrBackupInvalid, p.ID, p.PayerAccountID)
		}
		allowed := make(map[string]struct{}, len(p.AllowedAccountIDs))
		for j, id := range p.AllowedAccountIDs {
			if id == "" {
				return fmt.Errorf("%w: policy %q allowed account[%d] is empty", ErrBackupInvalid, p.ID, j)
			}
			if _, ok := accountIDs[id]; !ok {
				return fmt.Errorf("%w: policy %q references unknown allowed account %q", ErrBackupInvalid, p.ID, id)
			}
			if _, dup := allowed[id]; dup {
				return fmt.Errorf("%w: policy %q lists allowed account %q more than once", ErrBackupInvalid, p.ID, id)
			}
			allowed[id] = struct{}{}
		}
		if p.ReservedTotal < 0 || p.SpentTotal < 0 {
			return fmt.Errorf("%w: policy %q totals must not be negative (reserved %d spent %d)", ErrBackupInvalid, p.ID, p.ReservedTotal, p.SpentTotal)
		}
		po := &policy{
			id:                   p.ID,
			payerAccountID:       p.PayerAccountID,
			allowedAccounts:      allowed,
			operation:            p.Operation,
			payee:                p.Payee,
			startsAt:             p.StartsAt.std(),
			endsAt:               p.EndsAt.std(),
			maxPerRequest:        p.MaxPerRequest,
			maxTotal:             p.MaxTotal,
			approvalThreshold:    p.ApprovalThreshold,
			approvalWait:         p.ApprovalWait.std(),
			maxReserveDuration:   p.MaxReserveDuration.std(),
			reservedTotal:        p.ReservedTotal,
			spentTotal:           p.SpentTotal,
			deactivated:          p.Deactivated,
			deactivatedAt:        p.DeactivatedAt.std(),
			deactivatorAccountID: p.DeactivatorAccountID,
			deactivateReason:     p.DeactivateReason,
		}
		// 停用信息自洽：停用标志必须与停用时间/理由同时出现；停用账户必须
		// 存在；未停用不得携带任何停用记录。
		if po.deactivated {
			if po.deactivatedAt.IsZero() || po.deactivateReason == "" {
				return fmt.Errorf("%w: policy %q marked deactivated but missing deactivation time or reason", ErrBackupInvalid, p.ID)
			}
			if po.deactivatorAccountID != "" {
				if _, ok := accountIDs[po.deactivatorAccountID]; !ok {
					return fmt.Errorf("%w: policy %q deactivator references unknown account %q", ErrBackupInvalid, p.ID, po.deactivatorAccountID)
				}
			}
		} else if !po.deactivatedAt.IsZero() || po.deactivatorAccountID != "" || po.deactivateReason != "" {
			return fmt.Errorf("%w: policy %q not deactivated but carries deactivation info", ErrBackupInvalid, p.ID)
		}
		policyByID[p.ID] = po
		w.policies[p.ID] = po
	}

	// ---- 请求 ----
	if b.Requests == nil {
		return fmt.Errorf("%w: missing requests", ErrBackupInvalid)
	}
	reqKeys := make(map[requestKey]struct{}, len(b.Requests))
	reservedSumByPolicy := make(map[string]int64)
	spentSumByPolicy := make(map[string]int64)
	for i, r := range b.Requests {
		if err := validateRequestRef(r, i, accountIDs, sessionByID, policyByID); err != nil {
			return err
		}
		key := requestKey{accountID: r.AccountID, requestID: r.RequestID}
		if _, dup := reqKeys[key]; dup {
			return fmt.Errorf("%w: duplicate request id %q under account %q", ErrBackupInvalid, r.RequestID, r.AccountID)
		}
		reqKeys[key] = struct{}{}

		state := RequestState(r.State)
		if state < RequestReserved || state > RequestReservationExpired {
			return fmt.Errorf("%w: request %q/%q has unknown state %d", ErrBackupInvalid, r.AccountID, r.RequestID, r.State)
		}
		if r.EstimatedFee <= 0 {
			return fmt.Errorf("%w: request %q/%q estimated fee must be positive: %d", ErrBackupInvalid, r.AccountID, r.RequestID, r.EstimatedFee)
		}
		if r.ActualFee < 0 {
			return fmt.Errorf("%w: request %q/%q actual fee is negative: %d", ErrBackupInvalid, r.AccountID, r.RequestID, r.ActualFee)
		}
		if r.ReserveDuration.std() < 0 {
			return fmt.Errorf("%w: request %q/%q reserve duration is negative", ErrBackupInvalid, r.AccountID, r.RequestID)
		}

		req := &request{
			policyID:          r.PolicyID,
			requestID:         r.RequestID,
			accountID:         r.AccountID,
			payerAccountID:    r.PayerAccountID,
			sessionID:         r.SessionID,
			operation:         r.Operation,
			payee:             r.Payee,
			estimatedFee:      r.EstimatedFee,
			actualFee:         r.ActualFee,
			state:             state,
			createdAt:         r.CreatedAt.std(),
			settledAt:         r.SettledAt.std(),
			waitDeadline:      r.WaitDeadline.std(),
			reservedAt:        r.ReservedAt.std(),
			reserveDuration:   r.ReserveDuration.std(),
			reserveDeadline:   r.ReserveDeadline.std(),
			reserveExpiredAt:  r.ReserveExpiredAt.std(),
			decidedAt:         r.DecidedAt.std(),
			approverAccountID: r.ApproverAccountID,
			rejectReason:      r.RejectReason,
		}
		if err := validateRequestTimingAndState(req, policyByID[r.PolicyID], sessionByID[r.SessionID]); err != nil {
			return fmt.Errorf("%w: request %q/%q: %v", ErrBackupInvalid, r.AccountID, r.RequestID, err)
		}
		w.requests[key] = req

		// 累加各账户/策略“按请求推算”的金额，稍后与快照余额核对。
		// 只有当前仍处于已预留的请求才占用账户预留与策略预留总额。
		if state == RequestReserved {
			sum, ok := addInt64(reservedByAccount[req.payerAccountID], req.estimatedFee)
			if !ok {
				return fmt.Errorf("%w: account %q reserved sum overflows int64", ErrBackupInvalid, req.payerAccountID)
			}
			reservedByAccount[req.payerAccountID] = sum
			sum, ok = addInt64(reservedSumByPolicy[req.policyID], req.estimatedFee)
			if !ok {
				return fmt.Errorf("%w: policy %q reserved sum overflows int64", ErrBackupInvalid, req.policyID)
			}
			reservedSumByPolicy[req.policyID] = sum
		}
		if state == RequestSettled {
			sum, ok := addInt64(spentSumByPolicy[req.policyID], req.actualFee)
			if !ok {
				return fmt.Errorf("%w: policy %q spent sum overflows int64", ErrBackupInvalid, req.policyID)
			}
			spentSumByPolicy[req.policyID] = sum
		}
	}

	// ---- 账户预留余额 == 已预留请求预估费用之和 ----
	for id, acc := range w.accounts {
		if got, want := acc.reserved, reservedByAccount[id]; got != want {
			return fmt.Errorf("%w: account %q reserved %d != sum of reserved requests %d", ErrBackupInvalid, id, got, want)
		}
	}

	// ---- 可用余额 + 现存预留不得超过 int64 上限 ----
	// 取消或预留超时会把预留全额退回可用余额：合计一旦超出 MaxInt64，
	// 退回时余额就会越界变负。reservedByAccount 按出资账户汇总该账户在
	// 所有策略下仍处于已预留状态的费用（待审批不冻结费用，已结算、已取消、
	// 已预留超时的费用不再占用预留，故均不计入）。本检查必须在恢复时的
	// 到期自动退回之前完成，使“恢复即超时退款”的备份也不能蒙混过关；
	// 合计恰好等于上限合法（随后退回恰好得到上限金额）。
	for id, acc := range w.accounts {
		if _, ok := addInt64(acc.available, reservedByAccount[id]); !ok {
			return fmt.Errorf("%w: account %q available %d plus reserved %d overflows int64", ErrBackupInvalid, id, acc.available, reservedByAccount[id])
		}
	}

	// ---- 策略预留总额/已花费总额 == 请求求和，且合计不得超过累计上限 ----
	// 现存预留费用与已结算的实际费用共同占用策略的共享累计额度；同一策略的
	// 多个使用账户合计判断，不同策略分别判断。待审批不冻结费用，已取消、被
	// 拒绝、待审批过期、预留超时的请求均不计入，故上方求和本就不含它们。
	// 严格超过累计上限的备份自相矛盾（正常流程在受理时就会拒绝），必须整体
	// 拒绝；合计恰好等于上限合法。本检查针对备份保存的资金占用状态，位于
	// 恢复时的到期自动退回之前：即使某笔已预留请求恢复时已到期、将全额
	// 退回，也不能先退回再让原本超额的备份通过。两项金额各自为 int64、
	// 合计越过 int64 上限时，addInt64 先捕获溢出，不能误判为额度充足。
	for id, p := range policyByID {
		if got, want := p.reservedTotal, reservedSumByPolicy[id]; got != want {
			return fmt.Errorf("%w: policy %q reserved total %d != sum of reserved requests %d", ErrBackupInvalid, id, got, want)
		}
		if got, want := p.spentTotal, spentSumByPolicy[id]; got != want {
			return fmt.Errorf("%w: policy %q spent total %d != sum of settled requests %d", ErrBackupInvalid, id, got, want)
		}
		used, ok := addInt64(reservedSumByPolicy[id], spentSumByPolicy[id])
		if !ok {
			return fmt.Errorf("%w: policy %q reserved %d plus spent %d overflows int64 and exceeds cumulative total limit %d",
				ErrBackupInvalid, id, reservedSumByPolicy[id], spentSumByPolicy[id], p.maxTotal)
		}
		if used > p.maxTotal {
			return fmt.Errorf("%w: policy %q reserved %d plus spent %d exceeds cumulative total limit %d",
				ErrBackupInvalid, id, reservedSumByPolicy[id], spentSumByPolicy[id], p.maxTotal)
		}
	}

	// ---- 账本 ----
	if b.Ledger == nil {
		return fmt.Errorf("%w: missing ledger", ErrBackupInvalid)
	}
	w.ledger = make([]LedgerEntry, 0, len(b.Ledger))
	for i, e := range b.Ledger {
		kind := LedgerKind(e.Kind)
		if kind < LedgerReserve || kind > LedgerReservationExpiration {
			return fmt.Errorf("%w: ledger[%d] has unknown kind %d", ErrBackupInvalid, i, e.Kind)
		}
		if e.Amount < 0 {
			return fmt.Errorf("%w: ledger[%d] amount is negative: %d", ErrBackupInvalid, i, e.Amount)
		}
		// 账本是历史留痕：其账户/请求编号允许为空或指向不存在的实体。
		// 未被受理申请（必填字段缺失、使用账户或会话不存在等）同样会留下
		// 拒绝记录，这些记录必须原样保留，不能因为找不到对应账户或请求而
		// 丢弃或拒绝恢复。资金一致性由账户余额与现存请求的求和核对保证，
		// 不依赖账本文本。PolicyID 若给出则必须存在（仅策略停用记录使用）。
		if e.PolicyID != "" {
			if _, ok := policyByID[e.PolicyID]; !ok {
				return fmt.Errorf("%w: ledger[%d] references unknown policy %q", ErrBackupInvalid, i, e.PolicyID)
			}
		}
		w.ledger = append(w.ledger, LedgerEntry{
			Kind:      kind,
			AccountID: e.AccountID,
			RequestID: e.RequestID,
			PolicyID:  e.PolicyID,
			Amount:    e.Amount,
			Reason:    e.Reason,
			At:        e.At.std(),
		})
	}

	// ---- 恢复时按当前时间结清到期请求（不重新计时，只推进惰性状态） ----
	// 处理顺序与导出保持一致：先释放已到期预留，再把到期的待审批转为过期，
	// 两类记录均按各自截止时刻排序后追加到账本末尾。
	now := w.now()
	w.expireReservationsLocked(now)
	w.expirePendingApprovalsLocked(now)
	return nil
}

// validatePolicyParams 校验策略条件与限额参数，规则与 SavePolicy 一致。
func validatePolicyParams(p policyBackupV1) error {
	if p.Operation == "" || p.Payee == "" {
		return errors.New("operation and payee are required")
	}
	if p.MaxPerRequest <= 0 || p.MaxTotal <= 0 {
		return errors.New("limits must be positive")
	}
	if p.ApprovalThreshold < 0 {
		return errors.New("approval threshold must not be negative")
	}
	if p.ApprovalThreshold > 0 {
		if p.ApprovalThreshold > p.MaxPerRequest {
			return fmt.Errorf("approval threshold %d exceeds per-request limit %d", p.ApprovalThreshold, p.MaxPerRequest)
		}
		if p.ApprovalWait <= 0 {
			return errors.New("approval wait must be positive when approval is enabled")
		}
	}
	if p.ApprovalWait < 0 || p.MaxReserveDuration < 0 {
		return errors.New("durations must not be negative")
	}
	if !p.StartsAt.std().Before(p.EndsAt.std()) {
		return errors.New("starts-at must be before ends-at")
	}
	if p.PayerAccountID == "" || len(p.AllowedAccountIDs) == 0 {
		return errors.New("payer account and at least one allowed account are required")
	}
	return nil
}

// validateRequestRef 校验请求的外键引用：账户、会话、策略均须存在；申请
// 会话必须属于使用账户；出资账户必须与策略一致；申请账户必须被策略允许。
func validateRequestRef(r requestBackupV1, i int, accounts map[string]struct{}, sessions map[string]*session, policies map[string]*policy) error {
	where := fmt.Sprintf("request[%d] %q/%q", i, r.AccountID, r.RequestID)
	if r.RequestID == "" || r.AccountID == "" || r.PolicyID == "" || r.SessionID == "" {
		return fmt.Errorf("%w: %s missing required id (account/request/policy/session)", ErrBackupInvalid, where)
	}
	if _, ok := accounts[r.AccountID]; !ok {
		return fmt.Errorf("%w: %s references unknown usage account %q", ErrBackupInvalid, where, r.AccountID)
	}
	if _, ok := accounts[r.PayerAccountID]; !ok {
		return fmt.Errorf("%w: %s references unknown payer account %q", ErrBackupInvalid, where, r.PayerAccountID)
	}
	sess, ok := sessions[r.SessionID]
	if !ok {
		return fmt.Errorf("%w: %s references unknown session %q", ErrBackupInvalid, where, r.SessionID)
	}
	// 申请会话必须属于使用账户。
	if sess.accountID != r.AccountID {
		return fmt.Errorf("%w: %s session %q belongs to account %q, not usage account %q", ErrBackupInvalid, where, r.SessionID, sess.accountID, r.AccountID)
	}
	p, ok := policies[r.PolicyID]
	if !ok {
		return fmt.Errorf("%w: %s references unknown policy %q", ErrBackupInvalid, where, r.PolicyID)
	}
	// 请求出资账户必须与策略出资账户一致。
	if r.PayerAccountID != p.payerAccountID {
		return fmt.Errorf("%w: %s payer account %q does not match policy %q payer %q", ErrBackupInvalid, where, r.PayerAccountID, r.PolicyID, p.payerAccountID)
	}
	if _, ok := p.allowedAccounts[r.AccountID]; !ok {
		return fmt.Errorf("%w: %s usage account %q is not allowed by policy %q", ErrBackupInvalid, where, r.AccountID, r.PolicyID)
	}
	return nil
}

// validateReserveTiming 校验预留计时三元组自洽：duration 必须非负；
// duration>0 时 reservedAt 必填且 reserveDeadline 必须等于
// reservedAt+duration；duration==0 时 reserveDeadline 必须为零。
// reservedAt 是否必填由各状态自行决定（待审批取消的请求两者都没有）。
func validateReserveTiming(r *request) error {
	if r.reserveDuration < 0 {
		return errors.New("reserve duration must not be negative")
	}
	if r.reserveDuration > 0 {
		if r.reservedAt.IsZero() {
			return errors.New("reserve duration set but reserved_at is missing")
		}
		want := r.reservedAt.Add(r.reserveDuration)
		if !r.reserveDeadline.Equal(want) {
			return fmt.Errorf("reserve deadline %v does not match reserved_at+duration %v", r.reserveDeadline, want)
		}
	} else if !r.reserveDeadline.IsZero() {
		return errors.New("reserve deadline set while reserve duration is zero")
	}
	return nil
}

// validateSettlementTiming 校验已结算请求的结算时刻必须是正常结算能够产生的
// 历史：不早于实际预留时刻（恰在预留完成时结算可以接受）；当请求启用了预留
// 超时（reserveDuration>0，此时 reserveDeadline 已由 validateReserveTiming
// 确认为 reservedAt+duration）时，还必须严格早于预留截止时刻——恰到截止时刻
// 及之后预留已按超时规则全额退回，任何结算（含实际费用为零）都不可能成功。
//
// 时间一律按保存的完整时刻以 time.Time 的绝对瞬间比较（Equal/Before）：
// 纳秒精度保留，截止前不足一秒的合法结算不会被当成超时；不同时区表示的同一
// 时刻判定相同。关闭预留超时（reserveDuration==0）时没有截止时刻，沿用原有
// 结算规则、不人为增加期限。该校验只针对备份记载的预留与结算时刻，与恢复时
// 的当前时间无关：期限内完成的结算在很久以后恢复仍是已结算。
func validateSettlementTiming(r *request) error {
	if r.settledAt.Before(r.reservedAt) {
		return fmt.Errorf("settled_at %v is before reserved_at %v", r.settledAt, r.reservedAt)
	}
	if r.reserveDuration > 0 && !r.settledAt.Before(r.reserveDeadline) {
		return fmt.Errorf("settled_at %v is not within the valid reserve window ending strictly before reserve deadline %v", r.settledAt, r.reserveDeadline)
	}
	return nil
}

// validateRequestTimingAndState 校验请求状态与其计时/金额字段自洽，并与
// 不可变的策略条件、申请会话保持一致，防止任意状态搭配任意时间戳的损坏
// 备份。sess 为该请求的申请会话。
func validateRequestTimingAndState(r *request, p *policy, sess *session) error {
	if r.createdAt.IsZero() {
		return errors.New("request missing created_at")
	}
	if r.operation == "" || r.payee == "" {
		return errors.New("operation and payee are required")
	}
	if r.operation != p.operation || r.payee != p.payee {
		return fmt.Errorf("operation/payee do not match policy %q", p.id)
	}
	if r.estimatedFee > p.maxPerRequest {
		return fmt.Errorf("estimated fee %d exceeds policy per-request limit %d", r.estimatedFee, p.maxPerRequest)
	}
	if r.approverAccountID != "" && r.approverAccountID != r.payerAccountID {
		return fmt.Errorf("approver account %q is not the payer %q", r.approverAccountID, r.payerAccountID)
	}
	if r.actualFee > r.estimatedFee {
		return fmt.Errorf("actual fee %d exceeds estimated fee %d", r.actualFee, r.estimatedFee)
	}

	// 申请是否必须走过审批由不可变策略门槛决定：费用严格超过正门槛的请求
	// 只能来自待审批流程；其余请求只能直接预留。
	approvalRequired := p.approvalThreshold > 0 && r.estimatedFee > p.approvalThreshold
	reservedOrigin := !r.reservedAt.IsZero()

	switch r.state {
	case RequestReserved, RequestSettled, RequestReservationExpired:
		// 这三类一定发生过预留。
		if err := validateReservedOrigin(r, p, sess, approvalRequired, reservedOrigin); err != nil {
			return err
		}
	case RequestPendingApproval, RequestRejected, RequestExpired:
		// 这三类一定从未预留，且必须来自开启审批的策略。
		if err := validatePendingOrigin(r, p, approvalRequired, reservedOrigin); err != nil {
			return err
		}
	case RequestCancelled:
		// 取消可能来自待审批（从未预留）或已预留。
		if reservedOrigin {
			if err := validateReservedOrigin(r, p, sess, approvalRequired, true); err != nil {
				return err
			}
		} else {
			if err := validatePendingOrigin(r, p, approvalRequired, false); err != nil {
				return err
			}
		}
	default:
		return fmt.Errorf("unknown state %d", r.state)
	}

	switch r.state {
	case RequestReserved:
		// 启用超时时 deadline 必须等于 reservedAt + 时长，未启用时为零，
		// 且不得已记录超时。
		if err := validateReserveTiming(r); err != nil {
			return err
		}
		if !r.reserveExpiredAt.IsZero() {
			return errors.New("reserved request must not carry reserve-expired time")
		}
		if r.actualFee != 0 || !r.settledAt.IsZero() {
			return errors.New("reserved request must not be settled")
		}
		if r.rejectReason != "" {
			return errors.New("reserved request must not carry a reject reason")
		}
	case RequestSettled:
		if r.settledAt.IsZero() {
			return errors.New("settled request missing settled_at")
		}
		if !r.reserveExpiredAt.IsZero() {
			return errors.New("settled request must not carry reserve-expired time")
		}
		if err := validateReserveTiming(r); err != nil {
			return err
		}
		// 结算时刻必须落在有效预留期内：启用预留超时时严格早于截止时刻。
		if err := validateSettlementTiming(r); err != nil {
			return err
		}
		if r.rejectReason != "" {
			return errors.New("settled request must not carry a reject reason")
		}
	case RequestCancelled:
		if r.actualFee != 0 || !r.settledAt.IsZero() {
			return errors.New("cancelled request must not be settled")
		}
		if !r.reserveExpiredAt.IsZero() {
			return errors.New("cancelled request must not carry reserve-expired time")
		}
		if r.rejectReason != "" {
			return errors.New("cancelled request must not carry a reject reason")
		}
		if reservedOrigin {
			if err := validateReserveTiming(r); err != nil {
				return err
			}
		} else {
			// 待审批取消：决定时间必填。
			if r.decidedAt.IsZero() {
				return errors.New("cancelled-from-pending request missing decided_at")
			}
		}
	case RequestPendingApproval:
		// 待审批不冻结余额：不得有实际费用，且等待期限必须等于
		// min(提交+等待时长, 策略结束, 申请会话到期)。
		if r.actualFee != 0 || !r.settledAt.IsZero() {
			return errors.New("pending request must not be settled")
		}
		if r.waitDeadline.IsZero() {
			return errors.New("pending request missing wait deadline")
		}
		if r.approverAccountID != "" {
			return errors.New("pending request must not carry an approver")
		}
		if r.rejectReason != "" {
			return errors.New("pending request must not carry a reject reason")
		}
		if !r.waitDeadline.Equal(expectedWaitDeadline(r, p, sess)) {
			return fmt.Errorf("wait deadline %v does not match min(created+wait, policy end, session expiry) %v", r.waitDeadline, expectedWaitDeadline(r, p, sess))
		}
	case RequestRejected:
		if r.decidedAt.IsZero() || r.rejectReason == "" {
			return errors.New("rejected request missing decided_at or reason")
		}
	case RequestExpired:
		if r.decidedAt.IsZero() {
			return errors.New("expired request missing decided_at")
		}
		if r.rejectReason != "" {
			return errors.New("expired request must not carry a reject reason")
		}
		// 惰性/停用过期的决定时刻不可能早于等待截止时刻。
		if r.decidedAt.Before(r.waitDeadline) {
			return errors.New("expired request decided before its wait deadline")
		}
	case RequestReservationExpired:
		if r.reserveDuration <= 0 {
			return errors.New("reservation-expired request must have a positive reserve duration")
		}
		if err := validateReserveTiming(r); err != nil {
			return err
		}
		if !r.reserveExpiredAt.Equal(r.reserveDeadline) {
			return errors.New("reserve-expired-at must equal reserve deadline")
		}
		if r.actualFee != 0 || !r.settledAt.IsZero() {
			return errors.New("reservation-expired request must not be settled")
		}
		if r.rejectReason != "" {
			return errors.New("reservation-expired request must not carry a reject reason")
		}
	}
	return nil
}

// expectedWaitDeadline 计算审批路径请求的等待截止时刻：提交时刻 + 策略
// 等待时长、策略结束时间、申请会话到期时间三者中的最早值。待审批与已批准
// 预留的请求保存的等待截止时刻都必须与该值一致。
func expectedWaitDeadline(r *request, p *policy, sess *session) time.Time {
	want := r.createdAt.Add(p.approvalWait)
	if p.endsAt.Before(want) {
		want = p.endsAt
	}
	if sess.expiresAt.Before(want) {
		want = sess.expiresAt
	}
	return want
}

// validateApprovalTiming 校验“经批准后预留”的请求保存的等待期限与批准
// 时刻自洽，防止备份中的资金占用绕过正常审批等待期限：
//   - 等待截止时刻不得缺失，且必须等于提交时刻+等待时长、策略结束时间、
//     申请会话到期时间三者的最早值，提前或推迟都拒绝；
//   - 批准（决定/预留）时刻必须不早于提交时刻（恰在提交时刻批准可以接受），
//     且严格早于等待截止时刻：恰到截止时刻的批准在正常审批中不可能发生
//     （截止时刻及之后请求只能进入待审批过期终态）。
//
// 该校验只针对备份记载的批准历史，与恢复时的当前时间无关：期限内已批准的
// 请求在恢复时即使等待期限、申请会话或策略时间窗均已结束也照常恢复。
func validateApprovalTiming(r *request, p *policy, sess *session) error {
	if r.waitDeadline.IsZero() {
		return errors.New("approved request missing wait deadline")
	}
	want := expectedWaitDeadline(r, p, sess)
	if !r.waitDeadline.Equal(want) {
		return fmt.Errorf("wait deadline %v does not match min(created+wait, policy end, session expiry) %v", r.waitDeadline, want)
	}
	if r.decidedAt.Before(r.createdAt) {
		return fmt.Errorf("approval decided_at %v is before created_at %v", r.decidedAt, r.createdAt)
	}
	if !r.decidedAt.Before(r.waitDeadline) {
		return fmt.Errorf("approval decided_at %v is not strictly before wait deadline %v", r.decidedAt, r.waitDeadline)
	}
	return nil
}

// validateReservedOrigin 校验“发生过预留”的请求：预留计时字段必须齐全、
// 预留时长快照必须与策略一致，且审批路径（批准人、决定时间、等待期限）与
// 费用/门槛相匹配。对所有发生过预留的状态（已预留、已结算、预留超时、
// 已预留后取消）统一适用：超门槛的必须经出资账户在等待期限内于预留时刻
// 批准，未超门槛的直接受理、不得携带批准人或决定时间。
func validateReservedOrigin(r *request, p *policy, sess *session, approvalRequired, reservedOrigin bool) error {
	if !reservedOrigin {
		return errors.New("request is in a reserved-origin state but missing reserved_at")
	}
	if r.reserveDuration != p.maxReserveDuration {
		return fmt.Errorf("reserve duration %v does not match policy max reserve duration %v", r.reserveDuration, p.maxReserveDuration)
	}
	if approvalRequired {
		if r.approverAccountID != r.payerAccountID {
			return errors.New("above-threshold request was reserved without payer approval")
		}
		if !r.decidedAt.Equal(r.reservedAt) {
			return errors.New("approved request decided_at must equal reserved_at")
		}
		// 等待截止时刻与批准时刻必须是正常审批流程能够产生的历史：即使该
		// 预留后来已经结算、取消或超时退回，也不放宽这一要求。
		if err := validateApprovalTiming(r, p, sess); err != nil {
			return err
		}
	} else {
		if r.approverAccountID != "" {
			return errors.New("below-threshold request must not carry an approver")
		}
		if !r.decidedAt.IsZero() {
			return errors.New("directly reserved request must not carry decided_at")
		}
	}
	return nil
}

// validatePendingOrigin 校验“从未预留”的待审批系请求：不得携带任何预留
// 计时字段，且策略必须开启审批、费用必须严格超过门槛。
func validatePendingOrigin(r *request, p *policy, approvalRequired, reservedOrigin bool) error {
	if reservedOrigin {
		return errors.New("request is in a pending-origin state but carries reserved_at")
	}
	if !approvalRequired {
		return errors.New("request is in an approval state although policy approval is not enabled for its fee")
	}
	if !r.reserveDeadline.IsZero() || !r.reserveExpiredAt.IsZero() || r.reserveDuration != 0 {
		return errors.New("pending-origin request must not carry reserve timing")
	}
	return nil
}

