11	// buildMaxQuotaBackup 构造一份资金自洽的备份：策略 p-big 的单次与累计上限
12	// 均为 int64 最大值，含一笔已结算请求（预估 MaxInt64、实际 MaxInt64-1，
13	// 即已花费 MaxInt64-1），没有现存预留；出资账户可用余额由 available 指定。
14	// 使用账户 u1（会话 s1/设备 d1）、u2（会话 s2/设备 d2）共享额度。
15	// threshold>0 时策略开启审批（等待 1 小时），已结算大额请求按备份自洽要求
16	// 携带批准信息。
17	func buildMaxQuotaBackup(t *testing.T, t0 time.Time, threshold, available int64) []byte {
18		t.Helper()
19		const spent = math.MaxInt64 - 1
20		r := requestBackupV1{
21			PolicyID: "p-big", RequestID: "settled", AccountID: "u1", PayerAccountID: "payer",
22			SessionID: "s1", Operation: "charge", Payee: "shop",
23			EstimatedFee: math.MaxInt64, ActualFee: spent,
24			State:      int(RequestSettled),
25			CreatedAt:  timeJSON(t0.Add(-2 * time.Hour)),
26			ReservedAt: timeJSON(t0.Add(-2 * time.Hour)),
27			SettledAt:  timeJSON(t0.Add(-time.Hour)),
28		}
29		// 开启审批时该笔费用严格超过门槛，备份自洽要求带批准人、决定时刻与
30		// 等待截止时刻（提交于 t0-2h，等待 1h，故截止 t0-1h，批准于提交时刻）。
31		if threshold > 0 {
32			r.ApproverAccountID = "payer"
33			r.DecidedAt = r.ReservedAt
34			r.WaitDeadline = timeJSON(time.Time(r.CreatedAt).Add(time.Hour))
35		}
36		b := backupV1{
37			Version: backupVersion,
38			// ExportedAt 在校验中不使用，给出 t0 保持可读。
39			ExportedAt: timeJSON(t0),
40			Accounts: []accountBackupV1{
41				{ID: "payer", Available: available, Reserved: 0, CreatedAt: timeJSON(t0)},
42				{ID: "u1", Available: 0, Reserved: 0, CreatedAt: timeJSON(t0)},
43				{ID: "u2", Available: 0, Reserved: 0, CreatedAt: timeJSON(t0)},
44			},
45			Sessions: []sessionBackupV1{
46				{ID: "s1", AccountID: "u1", DeviceID: "d1", ExpiresAt: timeJSON(t0.Add(24 * time.Hour)), CreatedAt: timeJSON(t0)},
47				{ID: "s2", AccountID: "u2", DeviceID: "d2", ExpiresAt: timeJSON(t0.Add(24 * time.Hour)), CreatedAt: timeJSON(t0)},
48			},
49			Policies: []policyBackupV1{{
50				ID: "p-big", PayerAccountID: "payer", AllowedAccountIDs: []string{"u1", "u2"},
51				Operation: "charge", Payee: "shop",
52				StartsAt: timeJSON(t0.Add(-time.Hour)), EndsAt: timeJSON(t0.Add(24 * time.Hour)),
53				MaxPerRequest:     math.MaxInt64,
54				MaxTotal:          math.MaxInt64,
55				ApprovalThreshold: threshold,
56				ApprovalWait:      durationJSON(time.Hour),
57				SpentTotal:        spent,
58			}},
59			Requests: []requestBackupV1{r},
60			Ledger:   []ledgerEntryBackupV1{},
61		}
62		data, err := json.Marshal(&b)
63		if err != nil {
64			t.Fatal(err)
65		}
66		return data
67	}
