83	// TestApplySharedQuotaOverflowRejected 验证题述场景：累计上限为 int64 最大
84	// 值、已花费 MaxInt64-1、无现存预留、出资账户可用余额为 10 时，新申请预估
85	// 费用 2 必须按超额度拒绝（不能因求和越过 int64 上限被当成额度充足），费用
86	// 1 恰好把合计推到上限，应正常受理。
87	func TestApplySharedQuotaOverflowRejected(t *testing.T) {
88		t0 := time.Date(2026, 1, 1, 12, 0, 0, 0, time.UTC)
89		data := buildMaxQuotaBackup(t, t0, 0, 10)
90		w, err := restoreAt(data, t0)
91		if err != nil {
92			t.Fatalf("valid at-boundary backup must restore: %v", err)
93		}
94	
95		// 费用 2：used=MaxInt64-1，合计越过 int64 上限 → 超额度拒绝。
96		in := maxQuotaApply("u1", "s1", "d1", "over", 2)
97		if _, err := w.Apply(in); !errors.Is(err, ErrQuotaExceeded) {
98			t.Fatalf("apply fee 2 err = %v, want ErrQuotaExceeded", err)
99		}
100		// 不创建请求。
101		if _, err := w.Request("u1", "over"); !errors.Is(err, ErrRequestNotFound) {
102			t.Fatalf("rejected apply created request: %v", err)
103		}
104		// 不扣减可用余额、不新增预留。
105		if bal, _ := w.Balance("payer"); bal != (Balances{Available: 10, Reserved: 0}) {
106			t.Fatalf("balance after rejected apply = %+v, want {10 0}", bal)
107		}
108		pv, _ := w.Policy("p-big")
109		if pv.ReservedTotal != 0 || pv.SpentTotal != math.MaxInt64-1 {
110			t.Fatalf("policy totals after rejected apply = reserved %d spent %d", pv.ReservedTotal, pv.SpentTotal)
111		}
112		// 按现有申请拒绝规则留下一条带原因的拒绝记录，且无资金变动。
113		led := w.Ledger()
114		if len(led) != 1 || led[0].Kind != LedgerRejection || led[0].RequestID != "over" || led[0].Amount != 0 {
115			t.Fatalf("ledger after rejected apply = %+v", led)
116		}
117		if led[0].Reason == "" {
118			t.Fatal("rejection reason must not be empty")
119		}
120		if len(w.AccountLedger("payer")) != 0 {
121			t.Fatalf("rejected apply must not move payer money: %+v", w.AccountLedger("payer"))
122		}
123	
124		// 费用 1：合计恰好等于 MaxInt64 上限，正常受理并预留。
125		fit := maxQuotaApply("u1", "s1", "d1", "fit", 1)
126		req, err := w.Apply(fit)
127		if err != nil {
128			t.Fatalf("apply fee 1 at exact boundary: %v", err)
129		}
130		if req.State != RequestReserved {
131			t.Fatalf("fee 1 state = %v, want reserved", req.State)
132		}
133		if bal, _ := w.Balance("payer"); bal != (Balances{Available: 9, Reserved: 1}) {
134			t.Fatalf("balance after accepted apply = %+v, want {9 1}", bal)
135		}
136		pv, _ = w.Policy("p-big")
137		if pv.ReservedTotal != 1 || pv.SpentTotal != math.MaxInt64-1 {
138			t.Fatalf("policy totals after accepted apply = %+v", pv)
139		}
140	}
