142	// TestApplyOverflowRejectedBeforePending 验证进入待审批之前同样执行溢出安全
143	// 的累计额度判断：超过门槛、本应进入待审批的申请在超额时直接被拒绝，不留下
144	// 待审批请求或待审批留痕；恰好不超额的费用正常受理。
145	func TestApplyOverflowRejectedBeforePending(t *testing.T) {
146		t0 := time.Date(2026, 1, 1, 12, 0, 0, 0, time.UTC)
147		data := buildMaxQuotaBackup(t, t0, 1, 10)
148		w, err := restoreAt(data, t0)
149		if err != nil {
150			t.Fatalf("restore: %v", err)
151		}
152	
153		// 费用 2 严格超过门槛 1，本应待审批；但合计越过 int64 上限，必须在进入
154		// 待审批前以超额度拒绝。
155		in := maxQuotaApply("u1", "s1", "d1", "over-pending", 2)
156		if _, err := w.Apply(in); !errors.Is(err, ErrQuotaExceeded) {
157			t.Fatalf("apply err = %v, want ErrQuotaExceeded", err)
158		}
159		if _, err := w.Request("u1", "over-pending"); !errors.Is(err, ErrRequestNotFound) {
160			t.Fatalf("rejected apply created pending request: %v", err)
161		}
162		for _, e := range w.Ledger() {
163			if e.Kind == LedgerPendingApproval {
164				t.Fatalf("over-quota apply must not leave a pending-approval entry: %+v", e)
165			}
166		}
167		if bal, _ := w.Balance("payer"); bal != (Balances{Available: 10, Reserved: 0}) {
168			t.Fatalf("balance changed = %+v", bal)
169		}
170	
171		// 费用 1 不严格超过门槛，直接预留且合计恰好等于上限。
172		fit := maxQuotaApply("u1", "s1", "d1", "fit", 1)
173		req, err := w.Apply(fit)
174		if err != nil {
175			t.Fatalf("apply fee 1: %v", err)
176		}
177		if req.State != RequestReserved {
178			t.Fatalf("fee 1 state = %v, want reserved", req.State)
179		}
180	}
