200	// buildApproveOverflowBackup 构造批准溢出场景的自洽备份：
201	//   - 策略 p-big 单次/累计上限均为 MaxInt64，门槛 1、等待 1 小时，
202	//     最长预留时长 reserveDur（零表示关闭预留超时）；
203	//   - u1 一笔已结算实际费用 1（已花费 1，直接受理路径）；
204	//   - u2 一笔现存预留 big，预估 MaxInt64-2（批准路径，带批准信息），
205	//     预留时刻 t0、截止 t0+reserveDur；
206	//   - u1 一笔待审批 small，预估费用 2，提交于 t0，等待截止 t0+1h；
207	//   - 出资账户 payer 可用余额 2、预留余额 MaxInt64-2（可用+预留恰为
208	//     MaxInt64，备份自洽），现存预留与已花费合计 MaxInt64-1：再计入
209	//     small 的 2 会越过 int64 上限；
210	//   - 另有出资账户会话 sa（设备 dev-approve）供批准使用。
211	func buildApproveOverflowBackup(t *testing.T, t0 time.Time, reserveDur time.Duration) []byte {
212		t.Helper()
213		const (
214			spentActual = 1
215			bigFee      = math.MaxInt64 - 2
216			smallFee    = 2
217		)
218		settled := requestBackupV1{
219			PolicyID: "p-big", RequestID: "settled", AccountID: "u1", PayerAccountID: "payer",
220			SessionID: "s1", Operation: "charge", Payee: "shop",
221			EstimatedFee: spentActual, ActualFee: spentActual,
222			State:      int(RequestSettled),
223			CreatedAt:  timeJSON(t0.Add(-2 * time.Hour)),
224			ReservedAt: timeJSON(t0.Add(-2 * time.Hour)),
225			// 恰在预留完成时结算：无论是否启用预留超时都落在有效预留期起点，合法。
226			SettledAt: timeJSON(t0.Add(-2 * time.Hour)),
227		}
228		big := requestBackupV1{
229			PolicyID: "p-big", RequestID: "big", AccountID: "u2", PayerAccountID: "payer",
230			SessionID: "s2", Operation: "charge", Payee: "shop",
231			EstimatedFee:      bigFee,
232			State:             int(RequestReserved),
233			CreatedAt:         timeJSON(t0),
234			WaitDeadline:      timeJSON(t0.Add(time.Hour)),
235			ReservedAt:        timeJSON(t0),
236			ReserveDuration:   durationJSON(reserveDur),
237			ApproverAccountID: "payer",
238			DecidedAt:         timeJSON(t0),
239		}
240		if reserveDur > 0 {
241			big.ReserveDeadline = timeJSON(t0.Add(reserveDur))
242		}
243		small := requestBackupV1{
244			PolicyID: "p-big", RequestID: "small", AccountID: "u1", PayerAccountID: "payer",
245			SessionID: "s1", Operation: "charge", Payee: "shop",
246			EstimatedFee: smallFee,
247			State:        int(RequestPendingApproval),
248			CreatedAt:    timeJSON(t0),
249			WaitDeadline: timeJSON(t0.Add(time.Hour)),
250		}
251		// 已结算请求的预留时长快照必须与策略一致（备份自洽要求）。
252		settled.ReserveDuration = durationJSON(reserveDur)
253		if reserveDur > 0 {
254			settled.ReserveDeadline = timeJSON(t0.Add(-2 * time.Hour).Add(reserveDur))
255		}
256		b := backupV1{
257			Version:    backupVersion,
258			ExportedAt: timeJSON(t0),
259			Accounts: []accountBackupV1{
260				{ID: "payer", Available: 2, Reserved: bigFee, CreatedAt: timeJSON(t0)},
261				{ID: "u1", Available: 0, Reserved: 0, CreatedAt: timeJSON(t0)},
262				{ID: "u2", Available: 0, Reserved: 0, CreatedAt: timeJSON(t0)},
263			},
264			Sessions: []sessionBackupV1{
265				{ID: "s1", AccountID: "u1", DeviceID: "d1", ExpiresAt: timeJSON(t0.Add(24 * time.Hour)), CreatedAt: timeJSON(t0)},
266				{ID: "s2", AccountID: "u2", DeviceID: "d2", ExpiresAt: timeJSON(t0.Add(24 * time.Hour)), CreatedAt: timeJSON(t0)},
267				{ID: "sa", AccountID: "payer", DeviceID: "dev-approve", ExpiresAt: timeJSON(t0.Add(24 * time.Hour)), CreatedAt: timeJSON(t0)},
268			},
269			Policies: []policyBackupV1{{
270				ID: "p-big", PayerAccountID: "payer", AllowedAccountIDs: []string{"u1", "u2"},
271				Operation: "charge", Payee: "shop",
272				StartsAt: timeJSON(t0.Add(-time.Hour)), EndsAt: timeJSON(t0.Add(24 * time.Hour)),
273				MaxPerRequest:      math.MaxInt64,
274				MaxTotal:           math.MaxInt64,
275				ApprovalThreshold:  1,
276				ApprovalWait:       durationJSON(time.Hour),
277				MaxReserveDuration: durationJSON(reserveDur),
278				ReservedTotal:      bigFee,
279				SpentTotal:         spentActual,
280			}},
281			Requests: []requestBackupV1{settled, big, small},
282			Ledger:   []ledgerEntryBackupV1{},
283		}
284		data, err := json.Marshal(&b)
285		if err != nil {
286			t.Fatal(err)
287		}
288		return data
289	}
