296	// TestApproveSharedQuotaOverflowKeepsPending 验证待审批请求批准前重新执行
297	// 溢出安全的累计额度判断：其他请求已占用额度使本次批准越过 int64 上限时，
298	// 批准返回 ErrQuotaExceeded，请求继续待审批，提交时间、等待截止时间与决定
299	// 信息不变，不开始预留计时、不新增预留或批准记录；取消释放额度后期限内仍
300	// 可再次批准。
301	func TestApproveSharedQuotaOverflowKeepsPending(t *testing.T) {
302		t0 := time.Date(2026, 1, 1, 12, 0, 0, 0, time.UTC)
303		data := buildApproveOverflowBackup(t, t0, 0)
304		w, err := restoreAt(data, t0)
305		if err != nil {
306			t.Fatalf("restore: %v", err)
307		}
308		before, err := w.Request("u1", "small")
309		if err != nil {
310			t.Fatal(err)
311		}
312		if before.State != RequestPendingApproval {
313			t.Fatalf("setup state = %v, want pending", before.State)
314		}
315		// 余额恰好够（2），但额度合计 MaxInt64-1 再加 2 越过 int64 上限。
316		if bal, _ := w.Balance("payer"); bal != (Balances{Available: 2, Reserved: math.MaxInt64 - 2}) {
317			t.Fatalf("setup balance = %+v", bal)
318		}
319	
320		ledgerBefore := len(w.Ledger())
321		if _, err := approveSmall(w); !errors.Is(err, ErrQuotaExceeded) {
322			t.Fatalf("approve err = %v, want ErrQuotaExceeded", err)
323		}
324	
325		// 请求继续待审批，提交时间、等待截止时间与已有决定信息保持不变。
326		req, _ := w.Request("u1", "small")
327		if req.State != RequestPendingApproval {
328			t.Fatalf("state = %v, want still pending approval", req.State)
329		}
330		if !req.CreatedAt.Equal(before.CreatedAt) || !req.WaitDeadline.Equal(before.WaitDeadline) {
331			t.Fatalf("timing changed: created %v->%v deadline %v->%v",
332				before.CreatedAt, req.CreatedAt, before.WaitDeadline, req.WaitDeadline)
333		}
334		if !req.DecidedAt.Equal(time.Time{}) || req.ApproverAccountID != "" || req.RejectReason != "" {
335			t.Fatalf("decision fields changed on failed approve: %+v", req)
336		}
337		// 不开始预留计时。
338		if !req.ReservedAt.Equal(time.Time{}) || req.ReserveDuration != 0 || !req.ReserveDeadline.Equal(time.Time{}) {
339			t.Fatalf("reserve timing started on failed approve: %+v", req)
340		}
341		// 不新增预留或批准记录，余额与额度不变。
342		if got := len(w.Ledger()); got != ledgerBefore {
343			t.Fatalf("ledger grew by %d on failed approve", got-ledgerBefore)
344		}
345		if bal, _ := w.Balance("payer"); bal != (Balances{Available: 2, Reserved: math.MaxInt64 - 2}) {
346			t.Fatalf("balance changed after failed approve: %+v", bal)
347		}
348		pv, _ := w.Policy("p-big")
349		if pv.ReservedTotal != math.MaxInt64-2 || pv.SpentTotal != 1 {
350			t.Fatalf("policy totals changed after failed approve: %+v", pv)
351		}
352	
353		// 期限内额度未释放时再次批准仍被拒绝。
354		if _, err := approveSmall(w); !errors.Is(err, ErrQuotaExceeded) {
355			t.Fatalf("second approve err = %v, want ErrQuotaExceeded", err)
356		}
357	
358		// 取消 u2 的大额预留，释放 MaxInt64-2 共享额度并全额退回余额。
359		if _, err := w.Cancel("u2", "big"); err != nil {
360			t.Fatal(err)
361		}
362		if bal, _ := w.Balance("payer"); bal != (Balances{Available: math.MaxInt64, Reserved: 0}) {
363			t.Fatalf("balance after cancel big = %+v", bal)
364		}
365		// 仍在等待期限内（时钟停在 t0，截止 t0+1h），释放后批准成功并预留 2。
366		req, err = approveSmall(w)
367		if err != nil {
368			t.Fatalf("approve after quota freed: %v", err)
369		}
370		if req.State != RequestReserved {
371			t.Fatalf("state = %v, want reserved", req.State)
372		}
373		if bal, _ := w.Balance("payer"); bal != (Balances{Available: math.MaxInt64 - 2, Reserved: 2}) {
374			t.Fatalf("balance after approve small = %+v", bal)
375		}
376		pv, _ = w.Policy("p-big")
377		if pv.ReservedTotal != 2 || pv.SpentTotal != 1 {
378			t.Fatalf("policy totals after approve small = %+v", pv)
379		}
380	}
