382	// TestApproveOverflowReleasedByReservationTimeout 验证批准前的额度检查会计入
383	// 按现有规则已经到期的预留释放：大额预留超时自动全额退回、释放额度后，期限
384	// 内的待审批请求可以成功批准；释放之前仍按超额度拒绝。
385	func TestApproveOverflowReleasedByReservationTimeout(t *testing.T) {
386		t0 := time.Date(2026, 1, 1, 12, 0, 0, 0, time.UTC)
387		data := buildApproveOverflowBackup(t, t0, time.Minute)
388	
389		// 恢复于 t0：大额预留截止 t0+1m 尚未到期，批准 small 仍超额度。
390		w, err := restoreAt(data, t0)
391		if err != nil {
392			t.Fatalf("restore at t0: %v", err)
393		}
394		if _, err := approveSmall(w); !errors.Is(err, ErrQuotaExceeded) {
395			t.Fatalf("approve before timeout release err = %v, want ErrQuotaExceeded", err)
396		}
397		if r, _ := w.Request("u1", "small"); r.State != RequestPendingApproval {
398			t.Fatalf("small state = %v, want still pending", r.State)
399		}
400	
401		// 恢复于 t0+2m：大额预留已过截止时刻，恢复时自动全额退回并释放额度；
402		// small 的等待截止 t0+1h 尚未到，仍可批准。
403		w2, err := restoreAt(data, t0.Add(2*time.Minute))
404		if err != nil {
405			t.Fatalf("restore after deadline: %v", err)
406		}
407		if r, _ := w2.Request("u2", "big"); r.State != RequestReservationExpired {
408			t.Fatalf("big state = %v, want reservation expired", r.State)
409		}
410		if bal, _ := w2.Balance("payer"); bal != (Balances{Available: math.MaxInt64, Reserved: 0}) {
411			t.Fatalf("balance after timeout = %+v, want full refund", bal)
412		}
413		req, err := approveSmall(w2)
414		if err != nil {
415			t.Fatalf("approve after timeout release: %v", err)
416		}
417		if req.State != RequestReserved {
418			t.Fatalf("state = %v, want reserved", req.State)
419		}
420		if bal, _ := w2.Balance("payer"); bal != (Balances{Available: math.MaxInt64 - 2, Reserved: 2}) {
421			t.Fatalf("balance after approve small = %+v", bal)
422		}
423		pv, _ := w2.Policy("p-big")
424		if pv.ReservedTotal != 2 || pv.SpentTotal != 1 {
425			t.Fatalf("policy totals = %+v", pv)
426		}
427	}
428	
429	// TestApplyExactMaxInt64FillsQuota 验证单笔费用与上限均为 int64 最大值时
430	// 仍可正常受理（不缩小金额范围），占满后任何新费用都按超额度拒绝。
431	func TestApplyExactMaxInt64FillsQuota(t *testing.T) {
432		w, c := newTestWallet()
433		mustAccount(t, w, "payer", math.MaxInt64)
434		mustAccount(t, w, "u1", 0)
435		if _, err := w.CreateSession("s1", "u1", "d1", c.t.Add(time.Hour)); err != nil {
436			t.Fatal(err)
437		}
438		// 关闭审批：费用 MaxInt64 直接预留。
439		if err := w.SavePolicy(PolicySpec{
440			ID:                "p-direct",
441			PayerAccountID:    "payer",
442			AllowedAccountIDs: []string{"u1"},
443			Operation:         "charge",
444			Payee:             "shop",
445			StartsAt:          c.t.Add(-time.Hour),
446			EndsAt:            c.t.Add(24 * time.Hour),
447			MaxPerRequest:     math.MaxInt64,
448			MaxTotal:          math.MaxInt64,
449		}); err != nil {
450			t.Fatal(err)
451		}
452		in := RequestInput{
453			PolicyID: "p-direct", RequestID: "full", AccountID: "u1",
454			SessionID: "s1", DeviceID: "d1", Operation: "charge", Payee: "shop",
455			EstimatedFee: math.MaxInt64,
456		}
457		req, err := w.Apply(in)
458		if err != nil {
459			t.Fatalf("apply MaxInt64 fee: %v", err)
460		}
461		if req.State != RequestReserved {
462			t.Fatalf("state = %v, want reserved", req.State)
463		}
464		if bal, _ := w.Balance("payer"); bal != (Balances{Available: 0, Reserved: math.MaxInt64}) {
465			t.Fatalf("balance = %+v, want {0 MaxInt64}", bal)
466		}
467		// 额度已占满：再申请费用 1 必须超额度拒绝（used+1 越过 int64 上限；
468		// 余额虽同样不足，但额度判断在前，仍返回 ErrQuotaExceeded）。
469		in.RequestID = "one-more"
470		in.EstimatedFee = 1
471		if _, err := w.Apply(in); !errors.Is(err, ErrQuotaExceeded) {
472			t.Fatalf("apply after quota full err = %v, want ErrQuotaExceeded", err)
473		}
474	}
