		t.Fatal(err)
	}
	if err := w.SavePolicy(mkPolicy("p-notime", 0, 0, 0, 100, 1000)); err != nil {
		t.Fatal(err)
	}
	if err := w.SavePolicy(mkPolicy("p-deact", 0, 0, 0, 100, 1000)); err != nil {
		t.Fatal(err)
	}
	if _, err := w.DeactivatePolicy("p-deact", "sa", "deva", "stop it"); err != nil {
		t.Fatal(err)
